insert into public.academies (id, name) values ('linux', 'Academia de Linux')
on conflict (id) do nothing;

update public.courses
   set category = 'Linux', subcategory = 'Terminal y Sistemas', updated_at = now()
 where id in ('course-bash', 'course-consola-basica');

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-historia-linux', 'Historia de Linux: del Software Libre al Mundo Entero', 'De los mainframes de los años 50 a tu teléfono: Unix, el nacimiento del software libre con Stallman y GNU, Linus Torvalds en 1991, las distribuciones, el código abierto y cómo Linux terminó corriendo internet, Android y hasta un helicóptero en Marte. Con consolas interactivas para probar lo que aprendes.', 'Eres el Mago, profesor de la Academia de Linux de Oliver Academy, guiando el curso "Historia de Linux". Cuenta la historia como una aventura con personas reales (Thompson, Ritchie, Stallman, Torvalds, Murdock) y distingue siempre hechos verificables de anécdotas que se cuentan de una forma u otra. Explica conceptos técnicos (kernel, shell, distribución, licencia) con analogías simples, nunca asumas que el alumno ya usó Linux, y si pregunta por una fecha o cifra que no recuerdas con certeza, dilo en vez de inventarla.',
  '🐧', '#facc15', 'Linux', 'Historia y Cultura', 'principiante', false,
  '[{"type":"text","title":"Bienvenida: una historia de 60 años en una terminal","description":"De dónde viene el sistema que corre casi todo internet, y por qué su historia es también la historia de una idea.","content":"\n<h2>La historia que casi nadie te cuenta</h2>\n<p>Cuando abres una app en tu teléfono Android, cuando ves una película en una plataforma de streaming, cuando buscas algo en Google, cuando un banco procesa una transferencia… casi siempre hay <strong>Linux</strong> trabajando por debajo. Y sin embargo, hace 35 años era el pasatiempo de un estudiante finlandés de 21 años. ¿Cómo pasó?</p>\n<p>La respuesta no es solo técnica: es una historia de <strong>personas</strong>, de <strong>ideas sobre quién debe poder usar y cambiar el software</strong>, de demandas, de rivalidades y de una comunidad que aprendió a colaborar a escala mundial.</p>\n\n<h2>El mapa del curso</h2>\n<table>\n<tr><th>Parte</th><th>Qué vas a ver</th></tr>\n<tr><td>1. El mundo antes de Linux</td><td>Mainframes, Multics, el nacimiento de Unix en Bell Labs y las \"guerras Unix\".</td></tr>\n<tr><td>2. El nacimiento del software libre</td><td>Cuando el software empezó a venderse, Richard Stallman, GNU, la GPL y el copyleft.</td></tr>\n<tr><td>3. Linux</td><td>Linus Torvalds en 1991, el famoso debate con Tanenbaum, y por qué \"Linux\" y \"GNU/Linux\" no son lo mismo.</td></tr>\n<tr><td>4. Un ecosistema entero</td><td>Distribuciones, código abierto, empresas, Android, la nube y la comunidad.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Este curso tiene <strong>consolas interactivas</strong> en varias clases: son simuladas y seguras, para que pruebes los comandos que aparecen en la historia (pipes, uname, apt, git…). Cuando termines, prueba lo mismo en una terminal real o en el Laboratorio de terminales de la Academia de Linux.\n</div>\n\n<div class=\"warn\">\n⚠️ Una nota de honestidad: en la historia del software hay anécdotas que se cuentan de varias formas. Cuando algo sea una versión \"que se cuenta\" y no un hecho documentado, te lo diremos.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la idea central de este curso?","options":["Linux siempre fue un producto de una gran empresa","Linux es el resultado de décadas de ideas, personas y una comunidad colaborativa","Linux se inventó de la nada en un solo fin de semana","Linux solo sirve para servidores"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Antes de todo: los mainframes y el software compartido","description":"Cómo era programar en los años 50 y 60, y por qué entonces compartir software era lo normal.","content":"\n<h2>Computadoras del tamaño de una habitación</h2>\n<p>En los años 50 y 60 una computadora era un <strong>mainframe</strong>: un equipo enorme y carísimo que ocupaba una sala completa, propiedad de una universidad, un gobierno o una gran empresa. No había pantalla ni teclado para cada persona. Se trabajaba así: escribías tu programa en <strong>tarjetas perforadas</strong>, se las entregabas a un operador, esperabas horas (a veces un día) y recibías la salida impresa. Si tenías un error de una sola coma, volvías a empezar. A esto se le llamaba <strong>procesamiento por lotes</strong> (<em>batch</em>).</p>\n\n<h2>El software venía \"de regalo\"</h2>\n<p>Lo que hoy nos parece raro: en esa época el software casi <strong>no se vendía</strong>. El dinero estaba en el hardware, y los programas venían incluidos o se intercambiaban entre usuarios. En 1955 nació <strong>SHARE</strong>, un grupo de usuarios de IBM cuyo propósito era justamente compartir programas y mejoras entre organizaciones. Si alguien arreglaba un error, lo compartía; si alguien necesitaba una función, la pedía. Esa era la cultura: <em>el código circulaba</em>.</p>\n\n<h2>El tiempo compartido: la idea que lo cambió todo</h2>\n<p>Un problema era que la computadora pasaba mucho tiempo esperando a los humanos. La solución fue el <strong>tiempo compartido</strong> (<em>time-sharing</em>): que una misma máquina atendiera a <em>muchas personas a la vez</em>, cada una en su terminal, alternando entre ellas tan rápido que cada quien sentía que la máquina era suya. Uno de los primeros sistemas así fue <strong>CTSS</strong>, demostrado en el MIT en 1961. Esa idea — un sistema donde muchos usuarios comparten una máquina — es la semilla directa de Unix y, por herencia, de Linux.</p>\n\n<div class=\"example\">\n<strong>Piénsalo así:</strong> el procesamiento por lotes es como dejar tu ropa en una lavandería y volver mañana. El tiempo compartido es como tener tu propia lavadora, aunque en realidad compartas una lavandería enorme con cien personas.\n</div>\n\n<h2>El fin de la era \"todo compartido\"</h2>\n<p>En 1969, IBM (presionada, entre otras cosas, por investigaciones antimonopolio en Estados Unidos) anunció que empezaría a cobrar el software por separado del hardware. A esto se le llama <strong>unbundling</strong>. Poco a poco el software dejó de ser algo que se regalaba y se volvió un producto con dueño. Ese cambio, como verás, va a provocar una reacción.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué es el \"tiempo compartido\" (time-sharing)?","options":["Guardar el tiempo de uso de una computadora para cobrar más","Que una misma computadora atienda a muchas personas a la vez, alternando entre ellas muy rápido","Un sistema para apagar las computadoras automáticamente","Compartir el código fuente con otras empresas"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Multics y el nacimiento de Unix en Bell Labs","description":"Un proyecto ambicioso que fracasó a medias y dos ingenieros que decidieron hacer algo más simple.","content":"\n<h2>Multics: la idea grandiosa</h2>\n<p>En 1964, el MIT, General Electric y los <strong>Bell Labs</strong> (el laboratorio de investigación de AT&T) empezaron un proyecto ambicioso: <strong>Multics</strong>, un sistema de tiempo compartido con todas las funciones imaginables. Era tan grande y complejo que avanzaba lento. En 1969 Bell Labs se retiró del proyecto.</p>\n\n<h2>Dos ingenieros, una PDP-7 y una idea más simple</h2>\n<p>Dos de los investigadores que habían trabajado en Multics, <strong>Ken Thompson</strong> y <strong>Dennis Ritchie</strong>, extrañaban tener un entorno cómodo para programar. En 1969, Thompson encontró una computadora pequeña y poco usada (una <strong>PDP-7</strong>) y empezó a escribir un sistema mucho más sencillo, junto con Ritchie y otros colegas. Su nombre en broma fue <strong>\"Unics\"</strong> (un juego de palabras con Multics, atribuido a Brian Kernighan), que luego se convirtió en <strong>Unix</strong>.</p>\n\n<h2>El salto decisivo: escribirlo en C</h2>\n<p>Al principio Unix estaba escrito en ensamblador, atado a una máquina concreta. Ritchie creó un nuevo lenguaje, <strong>C</strong>, y entre 1972 y 1973 el núcleo de Unix se reescribió en C. Esto fue revolucionario: un sistema operativo escrito en un lenguaje de alto nivel podía <strong>llevarse a otras máquinas</strong> con relativamente poco esfuerzo. Esa portabilidad es una de las razones por las que Unix, y sus descendientes, están en todos lados hoy.</p>\n\n<h2>La filosofía Unix</h2>\n<p>Unix se hizo famoso por unas ideas de diseño muy simples, que se atribuyen sobre todo a <strong>Doug McIlroy</strong>:</p>\n<ul>\n<li>Haz programas pequeños que hagan <strong>una sola cosa</strong> y la hagan bien.</li>\n<li>Haz que los programas <strong>trabajen juntos</strong>.</li>\n<li>Usa <strong>texto</strong> como formato universal para intercambiar datos.</li>\n</ul>\n<p>La pieza que hace posible esto es el <strong>pipe</strong> (tubería), el símbolo <code>|</code>: toma la salida de un programa y la conecta como entrada del siguiente. Se implementó en Unix hacia 1973. Es tan buena idea que hoy sigue siendo la forma en que se combinan comandos en cualquier terminal Linux.</p>\n\n<pre><code>cat frutas.txt | sort | uniq -c</code></pre>\n\n<div class=\"tip\">\n💡 Lee ese comando de izquierda a derecha: <em>toma el archivo → ordénalo → cuenta las repeticiones</em>. Tres programas simples, un resultado útil. Eso es la filosofía Unix en una línea. Lo vas a practicar en la siguiente clase.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué fue tan importante reescribir Unix en C?","options":["Porque C era más bonito","Porque permitía llevar el sistema operativo a otras máquinas con relativamente poco esfuerzo (portabilidad)","Porque Multics estaba escrito en C","Porque así se podía vender más caro"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"🖥️ Consola Interactiva: la filosofía Unix con pipes","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Tienes un archivo frutas.txt con las frutas que se vendieron hoy. Vas a combinar programas pequeños con pipes, como en 1973.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: la filosofía Unix con pipes","intro":"Tienes un archivo frutas.txt con las frutas que se vendieron hoy. Vas a combinar programas pequeños con pipes, como en 1973.","checkpoints":[{"instruction":"Mira el contenido del archivo frutas.txt.","placeholder":"cat frutas.txt","pattern":"^cat\\s+frutas\\.txt\\s*$","hint":"Usa: cat frutas.txt","success":"cat muestra el archivo tal cual: sin orden y con repeticiones.","output":"manzana\nnaranja\nmanzana\nuva\nnaranja\nmanzana"},{"instruction":"Ordénalo alfabéticamente con el programa sort.","placeholder":"sort frutas.txt","pattern":"^sort\\s+frutas\\.txt\\s*$","hint":"Usa: sort frutas.txt","success":"sort hace una sola cosa: ordenar líneas.","output":"manzana\nmanzana\nmanzana\nnaranja\nnaranja\nuva"},{"instruction":"Ahora conecta sort con uniq -c usando un pipe (|) para contar cuántas veces aparece cada fruta.","placeholder":"sort frutas.txt | uniq -c","pattern":"^sort\\s+frutas\\.txt\\s*\\|\\s*uniq\\s+-c\\s*$","hint":"Usa: sort frutas.txt | uniq -c","success":"Dos programas simples, conectados: la salida de sort es la entrada de uniq.","output":"      3 manzana\n      2 naranja\n      1 uva"},{"instruction":"Último reto: agrega otro pipe con \"sort -rn\" para ordenar de más a menos vendida.","placeholder":"sort frutas.txt | uniq -c | sort -rn","pattern":"^sort\\s+frutas\\.txt\\s*\\|\\s*uniq\\s+-c\\s*\\|\\s*sort\\s+-rn\\s*$","hint":"Usa: sort frutas.txt | uniq -c | sort -rn","success":"Tres programas encadenados. La manzana es la más vendida. Eso es la filosofía Unix.","output":"      3 manzana\n      2 naranja\n      1 uva"}]},"id":3,"order":3},{"type":"text","title":"Unix se expande: universidades, Berkeley y las \"guerras Unix\"","description":"Cómo un sistema de un laboratorio llegó a todos lados, se dividió en muchas versiones… y se volvió un negocio.","content":"\n<h2>Una casualidad legal: Unix casi gratis para las universidades</h2>\n<p>AT&T era un monopolio telefónico, y desde 1956 un acuerdo con el gobierno de Estados Unidos le impedía dedicarse al negocio de las computadoras. Por eso no podía vender Unix como producto: lo <strong>licenciaba a universidades a un costo muy bajo</strong>, con el código fuente incluido. Miles de estudiantes aprendieron sistemas operativos leyendo Unix; un ejemplo famoso es el comentario del código de la versión 6 escrito por John Lions (1976), que circuló por todo el mundo en fotocopias.</p>\n\n<h2>Berkeley: BSD</h2>\n<p>En la Universidad de California en Berkeley, un grupo (con figuras como <strong>Bill Joy</strong>) mejoró Unix y empezó a distribuir su propia versión: <strong>BSD</strong> (<em>Berkeley Software Distribution</em>), desde 1977. Añadieron programas que aún usamos, como el editor <code>vi</code>, y con financiamiento de DARPA incorporaron el protocolo <strong>TCP/IP</strong> — el idioma de internet — en la versión 4.2BSD (1983). Esto convirtió a Unix en el sistema natural de internet.</p>\n\n<h2>1984: AT&T se divide… y Unix se vuelve negocio</h2>\n<p>En 1984 AT&T fue dividida por el gobierno de EE. UU. y, libre de la restricción, pudo vender Unix comercialmente. Las licencias se encarecieron y el código dejó de compartirse tan libremente. Al mismo tiempo, muchas empresas crearon su propia variante: <strong>SunOS/Solaris</strong> (Sun), <strong>AIX</strong> (IBM), <strong>HP-UX</strong> (HP), <strong>System V</strong> (AT&T)… Todas parecidas, todas ligeramente incompatibles. Se le llamó las <strong>\"guerras Unix\"</strong>.</p>\n\n<div class=\"example\">\n<strong>El resultado:</strong> un mundo lleno de \"sabores\" de Unix, casi todos <em>propietarios y caros</em>, que solo corrían en el hardware de cada fabricante. Para un estudiante o un aficionado, tener acceso a un Unix real era prácticamente imposible. Esa carencia es el escenario donde va a aparecer Linux.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué Unix llegó a tantas universidades al principio?","options":["Porque AT&T lo regalaba por publicidad","Porque un acuerdo legal le impedía a AT&T vender computadoras, así que lo licenciaba barato con el código fuente","Porque lo distribuía Microsoft","Porque era el único sistema que existía en 1970"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Cuando el software se volvió propiedad","description":"La otra mitad del contexto: la carta de Gates, los derechos de autor del software y la cultura hacker.","content":"\n<h2>Las computadoras llegan a casa</h2>\n<p>A mediados de los 70 aparecieron las primeras computadoras personales y con ellas una nueva generación de aficionados y empresas que empezaron a ver el software como <strong>un negocio</strong>. En febrero de 1976, un joven Bill Gates escribió su famosa <strong>\"Carta abierta a los aficionados\"</strong>, quejándose de que la gente copiaba su BASIC sin pagar. Era un anuncio del cambio de época: el software ya no era algo que se compartía, sino algo que se vendía y se protegía.</p>\n\n<h2>La ley se adapta</h2>\n<p>En 1980, Estados Unidos aprobó una reforma que dejó claro que los programas de computadora estaban protegidos por <strong>derechos de autor</strong> (copyright). Con eso, las empresas empezaron a distribuir software solo como <strong>binarios</strong> (el programa ya compilado), sin el <strong>código fuente</strong>, y con licencias que prohibían copiarlo, modificarlo o estudiarlo.</p>\n\n<table>\n<tr><th></th><th>Antes (años 50–70)</th><th>Después (años 80)</th></tr>\n<tr><td>¿Quién tiene el código fuente?</td><td>Casi siempre el usuario</td><td>Solo el fabricante</td></tr>\n<tr><td>¿Se puede modificar?</td><td>Sí, era normal</td><td>No, prohibido por licencia</td></tr>\n<tr><td>¿Se puede compartir?</td><td>Sí, era la cultura</td><td>Copiar se consideraba \"piratería\"</td></tr>\n</table>\n\n<h2>La cultura hacker</h2>\n<p>En los laboratorios de universidades como el MIT existía una comunidad de programadores apasionados —los <strong>hackers</strong>, en el sentido original: personas que aman entender cómo funcionan las cosas y mejorarlas—. Su ética se resumía en ideas como \"la información debe ser libre\" y \"el acceso a las computadoras debe ser ilimitado y total\". El periodista Steven Levy la describió en su libro <em>Hackers</em> (1984).</p>\n\n<div class=\"tip\">\n💡 Ojo con la palabra: \"hacker\" no significa \"criminal informático\". Ese es el sentido que le dio la prensa después. En este curso —y en la cultura Linux— un hacker es alguien curioso que construye y mejora cosas.\n</div>\n\n<p>Esa comunidad vio cómo su mundo de código compartido se disolvía. Una persona, en particular, decidió responder.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué cambió a principios de los 80 respecto al software?","options":["Se empezó a regalar más","Se volvió propiedad protegida por derechos de autor y se distribuyó sin código fuente","Dejó de existir el código fuente","Solo las universidades pudieron usarlo"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Richard Stallman, GNU y las cuatro libertades","description":"El origen del movimiento del software libre.","content":"\n<h2>Un programador del MIT y una impresora</h2>\n<p><strong>Richard Stallman</strong> trabajaba en el Laboratorio de Inteligencia Artificial del MIT, justo en esa comunidad hacker. Una anécdota famosa (que él mismo cuenta, con algunos detalles que varían según la versión) dice que a principios de los 80 una impresora nueva del laboratorio fallaba y él quiso arreglarla, como siempre había hecho, pero el fabricante se negó a darle el código fuente del controlador. Para Stallman, no poder arreglar una herramienta que usas todos los días fue el símbolo de lo que estaba mal con el nuevo mundo del software cerrado.</p>\n\n<h2>Septiembre de 1983: el anuncio de GNU</h2>\n<p>El <strong>27 de septiembre de 1983</strong> Stallman anunció en internet un proyecto: crear un sistema operativo completo, compatible con Unix, pero <strong>libre</strong>. Lo llamó <strong>GNU</strong>, un acrónimo recursivo (chiste de programadores) que significa <em>\"GNU''s Not Unix\"</em> — \"GNU no es Unix\". En 1984 dejó el MIT para dedicarse a ello, y en 1985 fundó la <strong>Free Software Foundation</strong> (FSF) y publicó el <em>Manifiesto GNU</em>.</p>\n\n<h2>Qué significa \"libre\" (no \"gratis\")</h2>\n<p>El software libre trata de <strong>libertad</strong>, no de precio (en inglés, <em>\"free as in freedom, not as in free beer\"</em>). La FSF lo define con <strong>cuatro libertades</strong>, numeradas desde cero (como hacen los programadores):</p>\n<table>\n<tr><th>Libertad</th><th>Qué te permite</th></tr>\n<tr><td>0</td><td>Ejecutar el programa como quieras, con cualquier propósito.</td></tr>\n<tr><td>1</td><td>Estudiar cómo funciona y modificarlo (requiere acceso al código fuente).</td></tr>\n<tr><td>2</td><td>Redistribuir copias para ayudar a otras personas.</td></tr>\n<tr><td>3</td><td>Distribuir copias de tus versiones modificadas, para que la comunidad se beneficie.</td></tr>\n</table>\n\n<h2>Las piezas de GNU</h2>\n<p>Stallman y sus colaboradores fueron construyendo, pieza por pieza, un sistema entero:</p>\n<ul>\n<li><strong>GNU Emacs</strong> (1985): un editor de texto extensible.</li>\n<li><strong>GCC</strong> (1987): el compilador de C, que hasta hoy compila casi todo el software libre.</li>\n<li><strong>Bash</strong> (1989, Brian Fox): la shell — el intérprete de comandos que usarás en este curso.</li>\n<li>Utilidades básicas (<code>ls</code>, <code>cp</code>, <code>grep</code>…), depurador (<code>gdb</code>), bibliotecas…</li>\n</ul>\n<p>Hacia 1990 GNU tenía casi todo lo necesario. Le faltaba una pieza clave: el <strong>kernel</strong>, el núcleo del sistema. Guarda ese detalle.</p>\n\n<div class=\"warn\">\n⚠️ Stallman es una figura importante y también controvertida en la comunidad. Como historia, lo relevante es su idea: que los usuarios deben tener control sobre el software que usan. Puedes estar de acuerdo con la idea o con parte de ella y aun así entender por qué cambió el mundo.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué significa \"software libre\" según la Free Software Foundation?","options":["Que no cuesta nada","Que respeta las libertades del usuario de ejecutarlo, estudiarlo, modificarlo y redistribuirlo","Que no tiene licencia","Que solo lo pueden usar universidades"],"correctIndex":1},"id":6,"order":6},{"type":"text","title":"La GPL y el copyleft: un truco legal brillante","description":"Cómo usar el copyright para proteger la libertad en vez de restringirla.","content":"\n<h2>El problema</h2>\n<p>Si simplemente publicas tu código \"para que todos lo usen\", alguien podría tomarlo, mejorarlo y volverlo <strong>cerrado</strong>, sin compartir sus mejoras. Tu obra libre acabaría alimentando software no libre.</p>\n\n<h2>La solución: copyleft</h2>\n<p>Stallman inventó (con ayuda de abogados) una licencia que usa las mismas leyes de copyright, pero al revés: la <strong>GNU General Public License</strong> (GPL). Dice, en esencia: <em>\"Puedes usar, copiar y modificar este programa, pero si lo distribuyes —modificado o no— debes hacerlo bajo la misma licencia y entregar el código fuente.\"</em> A esa idea se le llama <strong>copyleft</strong> (un juego de palabras con \"copyright\").</p>\n<p>La GPL versión 1 salió en 1989, la 2 en 1991 (la que usa el kernel Linux) y la 3 en 2007.</p>\n\n<h2>Licencias libres: dos grandes familias</h2>\n<table>\n<tr><th>Familia</th><th>Ejemplos</th><th>Idea</th></tr>\n<tr><td><strong>Copyleft</strong> (protegen que siga siendo libre)</td><td>GPL, LGPL, AGPL</td><td>Si distribuyes una versión modificada, debe seguir siendo libre.</td></tr>\n<tr><td><strong>Permisivas</strong> (casi sin condiciones)</td><td>MIT, BSD, Apache 2.0</td><td>Haz lo que quieras, incluso cerrarlo; solo conserva el aviso de autoría.</td></tr>\n</table>\n\n<div class=\"example\">\n<strong>Ejemplo:</strong> Linux usa GPL v2, por eso cualquier empresa que distribuya un dispositivo con Linux modificado debe ofrecer el código fuente de esas modificaciones. Muchos proyectos web, en cambio, usan MIT para que cualquiera pueda incluirlos en productos cerrados.\n</div>\n\n<div class=\"tip\">\n💡 Cuando publiques tu propio código, <strong>elige siempre una licencia</strong>. Sin licencia, legalmente nadie puede usar tu código, aunque esté en GitHub. Un sitio útil para decidir es choosealicense.com.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace el copyleft de la GPL?","options":["Prohíbe usar el software","Obliga a que las versiones modificadas que se distribuyan sigan siendo libres y con su código fuente","Permite cerrar el código si pagas","Solo aplica a software de universidades"],"correctIndex":1},"id":7,"order":7},{"type":"text","title":"🖥️ Consola Interactiva: lee una licencia","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Estás dentro de la carpeta de un proyecto. Antes de usar el código de otra persona, siempre lees su licencia.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: lee una licencia","intro":"Estás dentro de la carpeta de un proyecto. Antes de usar el código de otra persona, siempre lees su licencia.","checkpoints":[{"instruction":"Lista los archivos de la carpeta.","placeholder":"ls","pattern":"^ls\\s*$","hint":"Usa: ls","success":"Ahí está: un archivo LICENSE junto al código.","output":"LICENSE  README.md  main.c"},{"instruction":"Muestra solo las primeras 3 líneas del archivo LICENSE.","placeholder":"head -n 3 LICENSE","pattern":"^head\\s+-n\\s*3\\s+LICENSE\\s*$","hint":"Usa: head -n 3 LICENSE","success":"Es la licencia MIT, una de las permisivas.","output":"MIT License\n\nCopyright (c) 2026 Ada Torres"},{"instruction":"Busca en la licencia la palabra \"permission\" (sin importar mayúsculas) con grep -i.","placeholder":"grep -i permission LICENSE","pattern":"^grep\\s+-i\\s+[\"'']?permission[\"'']?\\s+LICENSE\\s*$","hint":"Usa: grep -i permission LICENSE","success":"grep encuentra las líneas que contienen esa palabra: aquí está la parte que te da permiso de usar el código.","output":"Permission is hereby granted, free of charge, to any person obtaining a copy"}]},"id":8,"order":8},{"type":"text","title":"BSD libre, la demanda y Minix: el terreno antes de Linux","description":"Por qué a principios de los 90 todavía no existía un Unix libre listo para usar.","content":"\n<h2>BSD se libera… y se complica</h2>\n<p>Durante los 80, los ingenieros de Berkeley fueron reescribiendo las partes de BSD que aún contenían código de AT&T, hasta que se pudo liberar casi todo. Hacia 1992 existía <strong>386BSD</strong>, una versión para PC. Pero ese año <strong>USL</strong> (la empresa de AT&T dueña de Unix) demandó a <strong>BSDi</strong>, una empresa que vendía un derivado de BSD, alegando que usaba código y secretos de Unix. El caso se resolvió en 1994, pero durante dos años creó <strong>incertidumbre legal</strong> sobre BSD. De esa época salieron <strong>FreeBSD</strong> y <strong>NetBSD</strong> (1993) y <strong>OpenBSD</strong> (1995), que siguen vivos hoy.</p>\n<p>Muchas personas piensan que esa nube legal ayudó a que la comunidad mirara hacia otro proyecto que estaba naciendo. Es una explicación popular, no la única.</p>\n\n<h2>Minix: un Unix para enseñar</h2>\n<p>En 1987, el profesor holandés <strong>Andrew Tanenbaum</strong> escribió <strong>Minix</strong>, un sistema tipo Unix pequeño, hecho para que sus estudiantes pudieran leer y entender un sistema operativo completo en un semestre (lo explicaba en su libro de texto). Corría en PCs baratos. Su código estaba disponible… pero con una licencia restrictiva: se podía estudiar, no se podía modificar ni redistribuir libremente. (Se liberó bajo una licencia tipo BSD hasta el año 2000.)</p>\n\n<h2>El rompecabezas en 1991</h2>\n<table>\n<tr><th>Pieza</th><th>Estado</th></tr>\n<tr><td>Herramientas (compilador, shell, utilidades)</td><td>✅ GNU las tenía casi todas, libres</td></tr>\n<tr><td>Kernel libre listo para usar</td><td>❌ GNU Hurd (empezado en 1990) aún estaba lejos; BSD tenía la nube legal; Minix era limitado y no libre del todo</td></tr>\n<tr><td>Un Unix accesible en un PC de casa</td><td>❌ Todavía no</td></tr>\n</table>\n<p>Faltaba una pieza. En un dormitorio universitario de Helsinki, alguien estaba a punto de escribirla.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué era Minix?","options":["Un videojuego","Un sistema tipo Unix pequeño creado por Tanenbaum para enseñar sistemas operativos","Un kernel de Microsoft","La primera versión de Linux"],"correctIndex":1},"id":9,"order":9},{"type":"text","title":"1991: Linus Torvalds y \"solo un pasatiempo\"","description":"El estudiante finlandés que empezó un kernel por curiosidad.","content":"\n<h2>Un estudiante en Helsinki</h2>\n<p><strong>Linus Torvalds</strong> nació en Helsinki (Finlandia) en 1969. Estudiaba en la Universidad de Helsinki, se había enamorado de Unix a través de Minix, y a principios de 1991 se compró una computadora con procesador <strong>Intel 386</strong>. Quería usarla para explorar cómo funcionaba el hardware… y no le gustaban las limitaciones de Minix. Así que empezó a escribir su propio <strong>kernel</strong>.</p>\n\n<h2>El kernel: el corazón del sistema</h2>\n<p>El <strong>kernel</strong> (núcleo) es la parte del sistema operativo que habla directamente con el hardware: administra la memoria, decide qué programa usa el procesador en cada momento, controla el disco, la red, los dispositivos. Todo lo demás —el navegador, la terminal, tus juegos— le pide cosas al kernel.</p>\n\n<h2>El mensaje del 25 de agosto de 1991</h2>\n<p>El 25 de agosto de 1991, Linus escribió en un grupo de noticias sobre Minix (<code>comp.os.minix</code>) algo parecido a esto (traducido y resumido): <em>\"Estoy haciendo un sistema operativo (gratis) — solo un pasatiempo, no será grande ni profesional como GNU— para clones AT 386/486. Llevo unos meses y ya empieza a estar listo. Me gustaría saber qué cosas les gustan o no les gustan de Minix.\"</em> Es uno de los mensajes más famosos de la historia de la informática: la promesa de que <em>no sería grande</em> resultó ser una de las predicciones más equivocadas.</p>\n\n<h2>Un nombre que no era el elegido</h2>\n<p>Linus pensaba llamarlo <strong>\"Freax\"</strong> (una mezcla de <em>free</em>, <em>freak</em> y X de Unix). Ari Lemmke, el administrador del servidor FTP de la universidad donde se publicó, creó el directorio con el nombre <strong>\"linux\"</strong> —de <em>Linus</em> + Unix—, y el nombre se quedó. La versión <strong>0.01</strong> se publicó en septiembre de 1991. A principios de 1992, con la versión 0.12, Linus cambió la licencia a la <strong>GPL</strong> de GNU, decisión clave: desde entonces, cualquiera podía mejorar Linux, pero nadie podía cerrarlo.</p>\n\n<h2>Hitos de versiones</h2>\n<table>\n<tr><th>Año</th><th>Versión</th><th>Detalle</th></tr>\n<tr><td>1991</td><td>0.01</td><td>Primera versión pública</td></tr>\n<tr><td>1994</td><td>1.0</td><td>Considerado \"estable\" por primera vez</td></tr>\n<tr><td>1996</td><td>2.0</td><td>Soporte para varios procesadores; llega el pingüino <strong>Tux</strong> como mascota</td></tr>\n<tr><td>2003</td><td>2.6</td><td>Salto grande en rendimiento y hardware soportado</td></tr>\n<tr><td>2011</td><td>3.0</td><td>Celebra los 20 años</td></tr>\n<tr><td>2022</td><td>6.0</td><td>Se sigue publicando una versión nueva cada 9–10 semanas aprox.</td></tr>\n</table>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace el kernel de un sistema operativo?","options":["Solo dibuja las ventanas","Habla con el hardware y administra memoria, procesador, disco y dispositivos para los demás programas","Es solo el navegador de internet","Guarda las contraseñas de los usuarios"],"correctIndex":1},"id":10,"order":10},{"type":"text","title":"🖥️ Consola Interactiva: conoce tu kernel","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Todo sistema Linux te dice qué kernel está corriendo. Vas a preguntarle a la máquina simulada.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: conoce tu kernel","intro":"Todo sistema Linux te dice qué kernel está corriendo. Vas a preguntarle a la máquina simulada.","checkpoints":[{"instruction":"Pregunta cuál es el nombre del kernel con uname -s.","placeholder":"uname -s","pattern":"^uname\\s+-s\\s*$","hint":"Usa: uname -s","success":"El kernel se llama Linux — el mismo nombre que le dio Ari Lemmke en 1991.","output":"Linux"},{"instruction":"Ahora pregunta la versión del kernel (release) con uname -r.","placeholder":"uname -r","pattern":"^uname\\s+-r\\s*$","hint":"Usa: uname -r","success":"Esa es la versión del kernel (el número exacto en tu computadora será distinto). Recuerda: la 0.01 fue en 1991.","output":"6.8.0-45-generic"},{"instruction":"Pide toda la información junta con uname -a.","placeholder":"uname -a","pattern":"^uname\\s+-a\\s*$","hint":"Usa: uname -a","success":"Sistema, nombre del equipo, versión del kernel y arquitectura, en una sola línea.","output":"Linux mi-laptop 6.8.0-45-generic #45-Ubuntu SMP x86_64 GNU/Linux"}]},"id":11,"order":11},{"type":"text","title":"El gran debate: Tanenbaum contra Torvalds","description":"Microkernels contra kernels monolíticos, en la discusión más famosa de la historia de Linux.","content":"\n<h2>\"Linux es obsoleto\"</h2>\n<p>En enero de 1992, Andrew Tanenbaum (el creador de Minix) publicó en el mismo grupo de noticias un mensaje titulado <strong>\"LINUX is obsolete\"</strong>. Argumentaba que el diseño del kernel de Linux ya estaba pasado de moda y que era un error hacerlo dependiente de un solo tipo de procesador. Linus respondió, y se armó una de las discusiones técnicas más famosas de internet.</p>\n\n<h2>El fondo técnico: dos formas de diseñar un kernel</h2>\n<table>\n<tr><th></th><th>Kernel monolítico</th><th>Microkernel</th></tr>\n<tr><td>Idea</td><td>Casi todo (drivers, sistema de archivos, red) corre dentro del kernel.</td><td>El kernel es mínimo; lo demás corre como programas separados.</td></tr>\n<tr><td>Ventaja</td><td>Rápido y más sencillo de programar.</td><td>Más limpio, y un fallo en un componente no tumba todo.</td></tr>\n<tr><td>Desventaja</td><td>Un error grave en un driver puede tumbar el sistema.</td><td>Comunicarse entre piezas cuesta rendimiento.</td></tr>\n<tr><td>Ejemplos</td><td>Linux, BSD clásico</td><td>Minix, GNU Hurd, QNX</td></tr>\n</table>\n<p>Tanenbaum defendía el microkernel como el futuro; Linus defendía el enfoque monolítico, más práctico. Con los años la historia dio la razón a Linus <em>en el mundo real</em> (Linux dominó), aunque los microkernels siguen siendo importantes en sistemas donde la fiabilidad es crítica.</p>\n\n<h2>La lección para ti</h2>\n<p>Tanenbaum tenía razón en algo: Linux estaba muy ligado al procesador x86 <em>en ese momento</em>. La historia demostró después que la portabilidad se podía lograr: hoy Linux corre en más arquitecturas que casi cualquier otro sistema. Las buenas ideas se mejoran discutiendo.</p>\n\n<div class=\"tip\">\n💡 Cuando trabajes en equipos, esto se repite todos los días: dos personas competentes que discrepan en el diseño. La clave que muestra esta historia es discutir con argumentos técnicos y quedarse con el resultado que funcione.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la principal diferencia entre un kernel monolítico y un microkernel?","options":["El monolítico solo funciona en un tipo de computadora","En el monolítico casi todo corre dentro del kernel; en el microkernel el kernel es mínimo y lo demás corre por separado","El microkernel es siempre más rápido","No hay ninguna diferencia"],"correctIndex":1},"id":12,"order":12},{"type":"text","title":"GNU + Linux: ¿cómo se arma un sistema completo?","description":"El kernel solo no es un sistema operativo. Las capas de un sistema Linux, y el debate del nombre.","content":"\n<h2>Linux, estrictamente, es solo el kernel</h2>\n<p>Lo que Linus escribió es un kernel. Para tener un sistema que puedas usar, hace falta mucho más. Y esas piezas ya existían: las había construido el proyecto GNU.</p>\n\n<h2>Las capas de un sistema Linux típico</h2>\n<table>\n<tr><th>Capa</th><th>Qué hace</th><th>Ejemplo (origen)</th></tr>\n<tr><td>Kernel</td><td>Habla con el hardware</td><td>Linux (Torvalds y la comunidad)</td></tr>\n<tr><td>Biblioteca C</td><td>Lo que usan los programas para pedirle cosas al kernel</td><td>glibc (GNU)</td></tr>\n<tr><td>Compilador</td><td>Convierte código en programas</td><td>GCC (GNU)</td></tr>\n<tr><td>Shell</td><td>Interpreta los comandos que escribes</td><td>Bash (GNU)</td></tr>\n<tr><td>Utilidades básicas</td><td>ls, cp, cat, grep…</td><td>GNU coreutils</td></tr>\n<tr><td>Sistema de arranque y servicios</td><td>Arranca la máquina y sus servicios</td><td>systemd u otros</td></tr>\n<tr><td>Entorno de escritorio</td><td>Ventanas, iconos, menús</td><td>GNOME, KDE Plasma, Xfce…</td></tr>\n</table>\n\n<h2>El debate del nombre</h2>\n<p>La FSF y Stallman piden llamar a estos sistemas <strong>GNU/Linux</strong>, porque gran parte del sistema es GNU y sin esas piezas Linux no habría sido usable. La mayoría de la gente dice simplemente <strong>Linux</strong>, por brevedad y porque es la marca que se popularizó. No hay una respuesta oficial correcta: ambas posturas tienen sentido, y conviene saber por qué existe la discusión.</p>\n\n<div class=\"warn\">\n⚠️ <strong>Android es la prueba de que el nombre importa.</strong> Android usa el kernel Linux, pero no usa las piezas de GNU (tiene su propia biblioteca C, llamada Bionic, y sus propias herramientas). Por eso Android <em>es Linux</em> (por el kernel) pero <em>no es GNU/Linux</em>.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué Android usa Linux pero no se le llama GNU/Linux?","options":["Porque Google no conoce GNU","Porque usa el kernel Linux pero no las herramientas y bibliotecas de GNU","Porque no usa kernel","Porque es un sistema de Microsoft"],"correctIndex":1},"id":13,"order":13},{"type":"text","title":"🖥️ Consola Interactiva: encuentra las piezas GNU","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a comprobar en un sistema Linux simulado que muchas herramientas cotidianas vienen del proyecto GNU.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: encuentra las piezas GNU","intro":"Vas a comprobar en un sistema Linux simulado que muchas herramientas cotidianas vienen del proyecto GNU.","checkpoints":[{"instruction":"Pregunta la versión de Bash con bash --version.","placeholder":"bash --version","pattern":"^bash\\s+--version\\s*$","hint":"Usa: bash --version","success":"Fíjate en el texto: \"GNU bash\" y el copyright de la Free Software Foundation.","output":"GNU bash, version 5.2.21(1)-release (x86_64-pc-linux-gnu)\nCopyright (C) 2022 Free Software Foundation, Inc."},{"instruction":"Ahora pregunta la versión del compilador con gcc --version.","placeholder":"gcc --version","pattern":"^gcc\\s+--version\\s*$","hint":"Usa: gcc --version","success":"GCC significa \"GNU Compiler Collection\". Lo empezó Stallman en 1987.","output":"gcc (Ubuntu 13.2.0-23ubuntu4) 13.2.0\nCopyright (C) 2023 Free Software Foundation, Inc."},{"instruction":"Por último, pregunta la versión de la biblioteca C con ldd --version.","placeholder":"ldd --version","pattern":"^ldd\\s+--version\\s*$","hint":"Usa: ldd --version","success":"glibc: la biblioteca de C de GNU, por donde pasan casi todos los programas para hablar con el kernel.","output":"ldd (Ubuntu GLIBC 2.39-0ubuntu8) 2.39"}]},"id":14,"order":14},{"type":"text","title":"Las distribuciones: cientos de sabores de Linux","description":"Slackware, Debian, Red Hat, Ubuntu, Arch… cómo se empaqueta Linux para que una persona pueda instalarlo.","content":"\n<h2>El problema de armar todo a mano</h2>\n<p>Instalar un sistema Linux \"a mano\" significaba conseguir el kernel, compilar cada herramienta y configurar todo. Poca gente podía hacerlo. Así nacieron las <strong>distribuciones</strong> (o <em>distros</em>): paquetes que reúnen el kernel, las herramientas GNU, un instalador y un <strong>gestor de paquetes</strong> para instalar programas fácilmente.</p>\n\n<h2>Las distribuciones históricas</h2>\n<table>\n<tr><th>Año</th><th>Distribución</th><th>Por qué importa</th></tr>\n<tr><td>1992–93</td><td>SUSE / Slackware</td><td>Primeras distros muy populares (SUSE en Alemania, Slackware de Patrick Volkerding).</td></tr>\n<tr><td>1993</td><td><strong>Debian</strong></td><td>Creada por Ian Murdock (su nombre viene de \"Debra\" y \"Ian\"). Comunitaria, sin dueño comercial. Una de las más influyentes.</td></tr>\n<tr><td>1994–95</td><td><strong>Red Hat</strong></td><td>Primera empresa en hacer un negocio grande con Linux, vendiendo soporte y servicios.</td></tr>\n<tr><td>2002</td><td>Arch Linux</td><td>Minimalista, para quien quiere construir su sistema pieza por pieza.</td></tr>\n<tr><td>2003</td><td>Fedora</td><td>Distro comunitaria patrocinada por Red Hat.</td></tr>\n<tr><td>2004</td><td><strong>Ubuntu</strong></td><td>Basada en Debian, creada por Mark Shuttleworth (Canonical). Se hizo famosa por ser fácil para principiantes.</td></tr>\n<tr><td>2006</td><td>Linux Mint</td><td>Basada en Ubuntu, muy amigable para quienes vienen de Windows.</td></tr>\n</table>\n\n<h2>Familias y gestores de paquetes</h2>\n<p>La mayoría de distros se agrupan por su \"familia\", y cada familia tiene su forma de instalar programas:</p>\n<table>\n<tr><th>Familia</th><th>Ejemplos</th><th>Gestor</th><th>Comando típico</th></tr>\n<tr><td>Debian</td><td>Debian, Ubuntu, Mint</td><td>apt</td><td><code>sudo apt install nombre</code></td></tr>\n<tr><td>Red Hat</td><td>Fedora, RHEL, Rocky, AlmaLinux</td><td>dnf</td><td><code>sudo dnf install nombre</code></td></tr>\n<tr><td>Arch</td><td>Arch, Manjaro</td><td>pacman</td><td><code>sudo pacman -S nombre</code></td></tr>\n</table>\n\n<div class=\"tip\">\n💡 <strong>¿Cuál elijo?</strong> Para empezar, Ubuntu o Linux Mint: mucha documentación, ayuda de la comunidad y todo funciona \"de fábrica\". Cuando quieras entender más, prueba Debian o Fedora. Arch es para cuando ya sepas por qué lo quieres.\n</div>\n\n<p>Otro dato: ninguna distro es \"la correcta\". Cada una responde a necesidades distintas: estabilidad para servidores, novedades para escritorio, ligereza para computadoras viejas, seguridad, o control total.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué es una distribución de Linux?","options":["Un virus que se distribuye por internet","Un paquete que reúne el kernel, herramientas, instalador y gestor de paquetes para usar Linux fácilmente","Solo el kernel Linux","Una tienda de aplicaciones de Google"],"correctIndex":1},"id":15,"order":15},{"type":"text","title":"🖥️ Consola Interactiva: identifica tu distro e instala un programa","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a descubrir en qué distribución estás y a instalar un programa con el gestor de paquetes apt (familia Debian/Ubuntu).</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: identifica tu distro e instala un programa","intro":"Vas a descubrir en qué distribución estás y a instalar un programa con el gestor de paquetes apt (familia Debian/Ubuntu).","checkpoints":[{"instruction":"Descubre qué distribución estás usando leyendo el archivo /etc/os-release.","placeholder":"cat /etc/os-release","pattern":"^cat\\s+/etc/os-release\\s*$","hint":"Usa: cat /etc/os-release","success":"Ahí dice: Ubuntu, de la familia Debian. Ese archivo existe en casi todas las distros modernas.","output":"PRETTY_NAME=\"Ubuntu 24.04 LTS\"\nNAME=\"Ubuntu\"\nID=ubuntu\nID_LIKE=debian"},{"instruction":"Actualiza la lista de programas disponibles con sudo apt update.","placeholder":"sudo apt update","pattern":"^sudo\\s+apt(-get)?\\s+update\\s*$","hint":"Usa: sudo apt update","success":"apt consultó los repositorios (servidores con miles de programas libres) para saber qué versiones hay.","output":"Hit:1 http://archive.ubuntu.com/ubuntu noble InRelease\nReading package lists... Done"},{"instruction":"Instala el programa cowsay con sudo apt install cowsay.","placeholder":"sudo apt install cowsay","pattern":"^sudo\\s+apt(-get)?\\s+install\\s+(-y\\s+)?cowsay\\s*$","hint":"Usa: sudo apt install cowsay","success":"Instalado. Un solo comando y el programa quedó listo, sin buscar instaladores en páginas web.","output":"Setting up cowsay (3.03+dfsg2-8) ..."},{"instruction":"Pruébalo: cowsay \"Hola Linux\".","placeholder":"cowsay \"Hola Linux\"","pattern":"^cowsay\\s+.+$","hint":"Usa: cowsay \"Hola Linux\" (con comillas)","success":"Un programa inútil pero divertido, y también libre — de eso se trata la cultura Linux.","output":" ______________\n< Hola Linux >\n --------------\n        \\   ^__^\n         \\  (oo)\\_______\n            (__)\\       )\\/\\\n                ||----w |\n                ||     ||"}]},"id":16,"order":16},{"type":"text","title":"Software libre vs. código abierto: 1998 y la Catedral y el Bazar","description":"Un cambio de nombre que cambió la conversación.","content":"\n<h2>La catedral y el bazar</h2>\n<p>En 1997 el programador <strong>Eric S. Raymond</strong> presentó un ensayo llamado <em>\"La catedral y el bazar\"</em>, que comparaba dos formas de desarrollar software:</p>\n<ul>\n<li><strong>La catedral:</strong> un pequeño grupo cerrado construye el software con cuidado y lo publica cuando está listo (así se hacía, por ejemplo, GNU Emacs en los 80).</li>\n<li><strong>El bazar:</strong> el desarrollo ocurre abiertamente, con muchísima gente aportando, publicando versiones a menudo y corrigiendo errores a la vista de todos. Raymond lo veía en cómo se desarrollaba Linux.</li>\n</ul>\n<p>Su famosa frase resume la idea: <em>\"con suficientes ojos, todos los errores son superficiales\"</em> — cuantas más personas miran el código, más rápido se encuentran y corrigen los fallos.</p>\n\n<h2>Netscape abre su código</h2>\n<p>En enero de 1998, la empresa <strong>Netscape</strong> (fabricante del navegador más usado de la época) anunció que liberaría el código fuente de su navegador. Fue una noticia enorme: una gran empresa comercial apostaba por abrir su código. De ese código nació después <strong>Mozilla</strong> y, con los años, <strong>Firefox</strong>.</p>\n\n<h2>Nace el término \"código abierto\"</h2>\n<p>Poco después, en febrero de 1998, un grupo de personas (entre ellas Raymond, Bruce Perens y Christine Peterson, a quien se le atribuye la propuesta del término) decidió que la expresión \"software libre\" asustaba a las empresas por su ambigüedad (¿libre o gratis?). Propusieron <strong>\"código abierto\"</strong> (<em>open source</em>) y fundaron la <strong>Open Source Initiative (OSI)</strong>.</p>\n\n<h2>Dos filosofías, muchas coincidencias</h2>\n<table>\n<tr><th></th><th>Software libre</th><th>Código abierto</th></tr>\n<tr><td>Enfoque</td><td>Ético: la libertad del usuario</td><td>Práctico: mejor software y mejor desarrollo</td></tr>\n<tr><td>Impulsado por</td><td>Free Software Foundation (Stallman)</td><td>Open Source Initiative (Raymond, Perens)</td></tr>\n<tr><td>Licencias</td><td>Casi las mismas en la práctica</td><td>Casi las mismas en la práctica</td></tr>\n</table>\n<p>En la práctica, casi todo el software libre es código abierto y viceversa. Por eso a veces se usa <strong>FOSS</strong> o <strong>FLOSS</strong> (<em>Free/Libre and Open Source Software</em>) para referirse a ambos, sin pelear por el nombre.</p>\n\n<h2>Microsoft y Linux: de enemigo a socio</h2>\n<p>En 1998 se filtraron memorandos internos de Microsoft (los <em>\"Halloween Documents\"</em>) que consideraban al código abierto una amenaza competitiva. En 2001 su director ejecutivo de entonces llegó a llamar a Linux \"un cáncer\". Años después la postura cambió por completo: en 2016 Microsoft lanzó el <strong>Subsistema de Windows para Linux</strong> (WSL) y se unió a la Linux Foundation, y desde 2019 WSL 2 incluye un kernel Linux real dentro de Windows. La industria entera aprendió que competir contra el código abierto era menos rentable que participar en él.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué se propuso el término \"código abierto\" en 1998?","options":["Porque \"software libre\" era ilegal","Porque el término \"libre\" se confundía con \"gratis\" y asustaba a las empresas; se buscaba una etiqueta más práctica","Porque Stallman lo pidió","Porque era un término de Microsoft"],"correctIndex":1},"id":17,"order":17},{"type":"text","title":"Linux llega a las empresas y conquista los servidores","description":"Cómo un proyecto de aficionados terminó en el centro de la industria.","content":"\n<h2>La web nació sobre software libre</h2>\n<p>A mediados de los 90 internet crecía y las empresas necesitaban servidores. El servidor web <strong>Apache</strong> (libre) se convirtió en el más usado del mundo, y junto con Linux, MySQL y PHP/Perl/Python formó la famosa pila <strong>LAMP</strong>: cientos de miles de sitios web corrían sobre software libre sin pagar licencias. Empresas como Google, en sus primeros años, construyeron su infraestructura con Linux por costo y control.</p>\n\n<h2>Hitos empresariales</h2>\n<table>\n<tr><th>Año</th><th>Hecho</th></tr>\n<tr><td>1999</td><td>Red Hat sale a bolsa (IPO) con un gran éxito; se vuelve el símbolo de que el código abierto puede ser un negocio.</td></tr>\n<tr><td>1999–2001</td><td>IBM anuncia inversiones de alrededor de mil millones de dólares en Linux: una empresa gigante apostando por él.</td></tr>\n<tr><td>2003</td><td>La empresa SCO demanda a IBM alegando que Linux contenía código de Unix. Años de pleitos, y los tribunales terminaron dando la razón a la comunidad y a Novell (dueña de los derechos de Unix).</td></tr>\n<tr><td>2007</td><td>Se funda la <strong>Linux Foundation</strong>, donde trabaja Linus Torvalds, para sostener el desarrollo del kernel.</td></tr>\n<tr><td>2012</td><td>Red Hat supera los mil millones de dólares de ingresos anuales: primera empresa de código abierto en lograrlo.</td></tr>\n<tr><td>2019</td><td>IBM completa la compra de Red Hat por unos 34,000 millones de dólares.</td></tr>\n</table>\n\n<h2>Supercomputadoras y la nube</h2>\n<ul>\n<li>Desde <strong>noviembre de 2017</strong>, el 100% de las 500 supercomputadoras más potentes del mundo (lista TOP500) corren Linux.</li>\n<li>La <strong>nube</strong> (Amazon AWS desde 2006, y después Google Cloud y Azure) funciona en gran parte sobre máquinas virtuales Linux.</li>\n<li>Los <strong>contenedores</strong> (Docker, 2013) y <strong>Kubernetes</strong> (2014), que hoy sostienen millones de aplicaciones, se apoyan en funciones del kernel Linux.</li>\n</ul>\n\n<div class=\"example\">\n<strong>Un ejemplo cotidiano:</strong> cuando pides un taxi en una app, ves una serie, compras en línea o transfieres dinero, es casi seguro que al menos una parte del camino pasó por servidores Linux.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué significa el dato de las supercomputadoras TOP500?","options":["Que Windows domina las supercomputadoras","Que desde 2017 todas las 500 más potentes corren Linux","Que ya no se usan supercomputadoras","Que solo IBM las fabrica"],"correctIndex":1},"id":18,"order":18},{"type":"text","title":"Linux en todos lados: Android, tu casa y hasta Marte","description":"Del bolsillo al espacio, y cómo Torvalds creó también Git.","content":"\n<h2>Android: el Linux que casi todos usan sin saberlo</h2>\n<p>Android Inc. se fundó en 2003 y Google la compró en 2005. En 2008 llegó el primer teléfono Android comercial (el HTC Dream / T-Mobile G1). Android usa el <strong>kernel Linux</strong> como base, y hoy miles de millones de dispositivos lo ejecutan: probablemente el kernel Linux más usado del planeta está en tu teléfono. (Y como viste, no es \"GNU/Linux\", porque no usa las herramientas GNU.)</p>\n\n<h2>Más lugares donde vive Linux</h2>\n<table>\n<tr><th>Dispositivo</th><th>Ejemplo</th></tr>\n<tr><td>Casa</td><td>Routers, televisores inteligentes, consolas y decodificadores</td></tr>\n<tr><td>Educación / hobby</td><td>Raspberry Pi (2012), una computadora de pocos dólares para aprender</td></tr>\n<tr><td>Juegos</td><td>Steam Deck (2022) usa SteamOS, basado en Arch Linux</td></tr>\n<tr><td>Laptops</td><td>ChromeOS (Chromebooks) está construido sobre el kernel Linux</td></tr>\n<tr><td>Autos y máquinas</td><td>Sistemas de información y entretenimiento de muchos autos, equipos industriales</td></tr>\n<tr><td>Espacio</td><td>El helicóptero <em>Ingenuity</em> de la NASA en Marte (2021) corría Linux — el primer Linux en otro planeta</td></tr>\n</table>\n\n<h2>Git: la segunda gran obra de Torvalds</h2>\n<p>Hasta 2005, los desarrolladores del kernel usaban una herramienta comercial llamada <strong>BitKeeper</strong>, cuya empresa les daba una licencia gratuita. Cuando esa relación se rompió, Torvalds decidió crear su propio sistema de control de versiones en pocas semanas: así nació <strong>Git</strong> (abril de 2005). Hoy Git es la herramienta estándar de casi toda la industria del software, y GitHub se construyó sobre él. Si quieres profundizar, la escuela incluye el curso <em>Git y GitHub: de Cero a Experto</em>.</p>\n\n<h2>El escritorio: el gran pendiente (y no tanto)</h2>\n<p>Linux dominó servidores, teléfonos y supercomputadoras, pero durante años se decía que \"aún no era el año de Linux en el escritorio\". Con Ubuntu, Steam Deck, mejoras en juegos (Proton) y el auge de WSL, su presencia crece, aunque en computadoras de escritorio todavía tiene una fracción pequeña frente a Windows y macOS. La historia sigue abierta.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué relación tiene Android con Linux?","options":["Ninguna","Android usa el kernel Linux como base","Android es una distribución Debian","Android es de Microsoft"],"correctIndex":1},"id":19,"order":19},{"type":"text","title":"La comunidad: cómo se desarrolla el kernel hoy","description":"Miles de personas, correo electrónico, mantenedores y una versión cada pocas semanas.","content":"\n<h2>Cómo se hace Linux</h2>\n<p>El kernel Linux es uno de los proyectos colaborativos más grandes de la historia. Miles de personas y empresas contribuyen. La forma de trabajar es sorprendentemente \"de la vieja escuela\":</p>\n<ol>\n<li>Alguien detecta un problema o quiere una mejora y escribe un <strong>parche</strong> (un cambio pequeño y concreto).</li>\n<li>Lo envía por <strong>correo electrónico</strong> a la lista de correo del kernel y a los <strong>mantenedores</strong> del área correspondiente (redes, sistemas de archivos, controladores…).</li>\n<li>Otros lo revisan, comentan y piden cambios, a veces con mucha franqueza.</li>\n<li>Si el mantenedor lo aprueba, sube en la cadena hasta Linus Torvalds (o sus lugartenientes), que lo incorpora en la ventana de cada versión.</li>\n<li>Cada 9–10 semanas aproximadamente sale una versión nueva.</li>\n</ol>\n\n<h2>Un \"dictador benevolente\"… con reglas</h2>\n<p>A Torvalds se le suele describir como \"dictador benevolente\": tiene la última palabra, pero delega en mantenedores de confianza. En 2018, tras críticas por el tono agresivo de sus revisiones, Linus se disculpó y se tomó un tiempo de descanso; la comunidad adoptó un <strong>Código de Conducta</strong> para que la colaboración fuera más respetuosa. Es un recordatorio de que un proyecto técnico también es un proyecto humano.</p>\n\n<h2>Rust llega al kernel</h2>\n<p>Durante más de treinta años el kernel se escribió en C. Desde la versión 6.1 (finales de 2022) se aceptan también componentes escritos en <strong>Rust</strong>, un lenguaje pensado para evitar clases enteras de errores de memoria. Es un cambio histórico, y una muestra de que Linux sigue evolucionando.</p>\n\n<h2>Tú también puedes verlo</h2>\n<p>Todo el código del kernel es público. En la consola de esta clase vas a \"descargar\" el repositorio y mirar su estructura, como haría cualquier persona que quiera aprender leyendo el código real de Linux.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cómo se envían normalmente los cambios al kernel Linux?","options":["Mediante una aplicación móvil","Por correo electrónico, como parches, que revisan los mantenedores","Solo pagando una licencia","Solo Linus puede escribir código"],"correctIndex":1},"id":20,"order":20},{"type":"text","title":"🖥️ Consola Interactiva: explora el código fuente de Linux","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>El kernel vive en un repositorio Git público. Vas a clonarlo (con --depth 1 baja solo la última versión, mucho más rápido) y a mirar su estructura.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: explora el código fuente de Linux","intro":"El kernel vive en un repositorio Git público. Vas a clonarlo (con --depth 1 baja solo la última versión, mucho más rápido) y a mirar su estructura.","checkpoints":[{"instruction":"Clona el repositorio del kernel: git clone --depth 1 https://github.com/torvalds/linux.git","placeholder":"git clone --depth 1 https://github.com/torvalds/linux.git","pattern":"^git\\s+clone\\s+(--depth[ =]1\\s+)?https://github\\.com/torvalds/linux(\\.git)?\\s*$","hint":"Usa: git clone --depth 1 https://github.com/torvalds/linux.git","success":"Ese es el repositorio real. Cualquier persona en el mundo puede descargarlo y leerlo.","output":"Cloning into ''linux''...\nReceiving objects: 100% done."},{"instruction":"Entra a la carpeta con cd linux.","placeholder":"cd linux","pattern":"^cd\\s+linux/?\\s*$","hint":"Usa: cd linux","success":"Ya estás dentro del código fuente del kernel."},{"instruction":"Lista las carpetas con ls.","placeholder":"ls","pattern":"^ls\\s*$","hint":"Usa: ls","success":"Fíjate: \"drivers\" (los controladores, la parte más grande), \"fs\" (sistemas de archivos), \"net\" (red), \"kernel\" (el núcleo), \"Documentation\"… y el archivo COPYING con la licencia GPL.","output":"arch  block  certs  crypto  Documentation  drivers  fs  include  init  ipc  kernel  lib  LICENSES  mm  net  rust  samples  scripts  security  sound  tools  virt\nCOPYING  CREDITS  Kbuild  Kconfig  MAINTAINERS  Makefile  README"}]},"id":21,"order":21},{"type":"text","title":"Cómo participar tú: tu ruta en el mundo Linux","description":"No hace falta ser programador ni experto para ser parte de esta historia.","content":"\n<h2>Contribuir no es solo programar</h2>\n<p>Cuando la gente piensa en \"contribuir al código abierto\" imagina escribir código para el kernel. Pero los proyectos libres necesitan mucho más:</p>\n<table>\n<tr><th>Si sabes hacer…</th><th>Puedes contribuir con…</th></tr>\n<tr><td>Usar Linux</td><td>Reportar errores claros (qué hiciste, qué esperabas, qué pasó).</td></tr>\n<tr><td>Escribir bien</td><td>Mejorar la documentación y los tutoriales.</td></tr>\n<tr><td>Hablar otros idiomas</td><td>Traducir programas y documentación.</td></tr>\n<tr><td>Diseñar</td><td>Iconos, temas, interfaces.</td></tr>\n<tr><td>Ayudar a otros</td><td>Responder preguntas en foros y comunidades.</td></tr>\n<tr><td>Programar</td><td>Corregir errores pequeños en proyectos con la etiqueta \"good first issue\".</td></tr>\n</table>\n\n<h2>Tu plan práctico</h2>\n<ol>\n<li><strong>Prueba Linux sin arriesgar nada:</strong> usa una máquina virtual, un USB \"Live\" (arranca sin instalar) o WSL en Windows.</li>\n<li><strong>Aprende la terminal:</strong> los cursos <em>Consola de Comandos: Primeros Pasos</em> y <em>Bash desde Cero</em> de esta academia son el siguiente paso natural.</li>\n<li><strong>Lleva Linux en tu teléfono:</strong> el curso de <em>Termux</em> te enseña a tener una terminal Linux en tu Android.</li>\n<li><strong>Aprende Git:</strong> es el idioma común de toda contribución.</li>\n<li><strong>Elige un proyecto pequeño que uses</strong> y lee su guía de contribución.</li>\n</ol>\n\n<div class=\"warn\">\n⚠️ <strong>Ética y legalidad:</strong> Linux incluye herramientas muy poderosas (redes, seguridad, administración). Úsalas solo en equipos y redes que sean tuyos o con autorización expresa. Aprender es libre; atacar sistemas ajenos, no.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál de estas es una forma válida de contribuir al software libre sin escribir código?","options":["Ninguna: solo se contribuye programando","Traducir, documentar, reportar errores o ayudar a otros usuarios","Copiar el software y venderlo como propio","Cambiar la licencia sin permiso"],"correctIndex":1},"id":22,"order":22},{"type":"text","title":"Línea de tiempo completa y examen final","description":"Repasa la historia entera de un vistazo y demuestra lo que aprendiste.","content":"\n<h2>Línea de tiempo</h2>\n<table>\n<tr><th>Año</th><th>Hecho</th></tr>\n<tr><td>1955</td><td>SHARE: usuarios de IBM comparten software.</td></tr>\n<tr><td>1961–64</td><td>CTSS (tiempo compartido) y arranque del proyecto Multics.</td></tr>\n<tr><td>1969</td><td>Thompson y Ritchie empiezan Unix en Bell Labs. IBM comienza a cobrar el software por separado.</td></tr>\n<tr><td>1972–73</td><td>Nace el lenguaje C; Unix se reescribe en C; aparecen los pipes.</td></tr>\n<tr><td>1977–83</td><td>BSD en Berkeley; TCP/IP en 4.2BSD.</td></tr>\n<tr><td>1983</td><td>Stallman anuncia el proyecto GNU (27 de septiembre).</td></tr>\n<tr><td>1984</td><td>AT&T se divide y puede vender Unix.</td></tr>\n<tr><td>1985</td><td>Se funda la Free Software Foundation.</td></tr>\n<tr><td>1987</td><td>Minix (Tanenbaum) y GCC.</td></tr>\n<tr><td>1989–91</td><td>Bash, GPL v1 y v2.</td></tr>\n<tr><td>1991</td><td><strong>Linus Torvalds anuncia Linux (25 de agosto).</strong></td></tr>\n<tr><td>1992</td><td>Debate Tanenbaum–Torvalds; Linux pasa a la GPL; demanda USL vs. BSDi.</td></tr>\n<tr><td>1993</td><td>Nacen Debian y Slackware.</td></tr>\n<tr><td>1994–95</td><td>Linux 1.0; Red Hat.</td></tr>\n<tr><td>1998</td><td>Netscape abre su código; nace el término \"código abierto\" y la OSI.</td></tr>\n<tr><td>1999–2003</td><td>Red Hat sale a bolsa; IBM invierte en Linux; demanda de SCO.</td></tr>\n<tr><td>2004</td><td>Ubuntu.</td></tr>\n<tr><td>2005</td><td>Torvalds crea Git.</td></tr>\n<tr><td>2007</td><td>Linux Foundation; GPL v3.</td></tr>\n<tr><td>2008</td><td>Primer teléfono Android.</td></tr>\n<tr><td>2016–19</td><td>WSL de Microsoft; IBM compra Red Hat.</td></tr>\n<tr><td>2017</td><td>El 100% del TOP500 corre Linux.</td></tr>\n<tr><td>2021–22</td><td>Linux cumple 30 años; Ingenuity vuela en Marte; Rust llega al kernel.</td></tr>\n</table>\n\n<h2>Lo que te llevas</h2>\n<ul>\n<li>Linux no es una obra aislada: se apoya en <strong>Unix</strong> (ideas), <strong>GNU</strong> (herramientas y licencia) y una <strong>comunidad</strong> (código).</li>\n<li>Su éxito se explica tanto por lo técnico como por lo humano: una licencia que protege la libertad y una forma abierta de colaborar.</li>\n<li>La historia sigue: <strong>tú</strong> puedes ser parte.</li>\n</ul>\n\n<div class=\"tip\">\n💡 <strong>Siguiente paso recomendado:</strong> el curso <em>Consola de Comandos: Primeros Pasos</em> y después <em>Bash desde Cero</em> — allí empieza la parte práctica. Y si quieres llevar Linux en tu teléfono, el curso de <em>Termux</em>.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Quién anunció el proyecto GNU en 1983 con la meta de crear un sistema operativo libre tipo Unix?","options":["Linus Torvalds","Richard Stallman","Andrew Tanenbaum","Bill Gates"],"correctIndex":1},"id":23,"order":23}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-termux', 'Termux: Linux en tu Bolsillo', 'Convierte tu teléfono Android en una terminal Linux de verdad, sin root: instala Termux bien, aprende pkg, scripts, Python, Git, SSH, la API del teléfono, automatizaciones y hasta una distro Debian completa con proot-distro. Con consolas interactivas para practicar cada paso.', 'Eres el Mago, profesor de la Academia de Linux de Oliver Academy, guiando el curso "Termux: Linux en tu Bolsillo". Explica con paciencia y sin asumir experiencia previa en terminal; recuerda siempre que Termux NO requiere root, que hay que instalarlo desde F-Droid o GitHub (no de versiones antiguas de tiendas) y que las herramientas de red o seguridad solo se usan en dispositivos y redes propios o con autorización expresa. Si el alumno tiene un error concreto de su teléfono, pídele el mensaje exacto y la versión de Android antes de suponer la causa.',
  '📱', '#22c55e', 'Linux', 'Linux en Móvil', 'principiante', false,
  '[{"type":"text","title":"Bienvenida: qué es Termux y qué puedes hacer con él","description":"Una terminal Linux completa en tu Android, sin root ni computadora.","content":"\n<h2>Una terminal de verdad en tu bolsillo</h2>\n<p><strong>Termux</strong> es una aplicación para Android que te da una <strong>terminal</strong> y un <strong>entorno Linux</strong> con miles de programas instalables: Python, Git, editores, servidores, herramientas de red… Todo dentro de tu teléfono, <strong>sin necesidad de root</strong> (no tienes que \"desbloquear\" ni modificar el sistema de tu teléfono). Es software libre, creado por Fredrik Fornwall y mantenido por una comunidad abierta.</p>\n\n<h2>¿Por qué funciona?</h2>\n<p>Recuerda el curso de <em>Historia de Linux</em>: Android está construido sobre el <strong>kernel Linux</strong>. Termux aprovecha eso: como Android ya es Linux \"por debajo\", puede correr programas de Linux normales, compilados para tu teléfono, dentro de su propia carpeta protegida (tu aplicación no puede tocar lo demás del sistema).</p>\n\n<h2>¿Qué NO es Termux?</h2>\n<table>\n<tr><th>Mito</th><th>Realidad</th></tr>\n<tr><td>\"Es una herramienta para hackear\"</td><td>Es una terminal. Incluye herramientas de todo tipo (desarrollo, redes, seguridad); lo que hagas con ellas es tu responsabilidad y solo es legal en sistemas propios o con permiso.</td></tr>\n<tr><td>\"Necesita root\"</td><td>No. Funciona con un teléfono normal.</td></tr>\n<tr><td>\"Es un emulador de Linux\"</td><td>No emula nada: los programas corren de forma nativa en el procesador de tu teléfono.</td></tr>\n<tr><td>\"Es Ubuntu/Debian\"</td><td>No exactamente. Es su propio entorno (usa la biblioteca de Android). Puedes instalar una distro completa dentro con <code>proot-distro</code>, como verás al final.</td></tr>\n</table>\n\n<h2>Lo que vas a poder hacer al terminar</h2>\n<ul>\n<li>Usar los comandos de Linux desde tu teléfono.</li>\n<li>Escribir y ejecutar <strong>scripts</strong> y programas en <strong>Python</strong>.</li>\n<li>Usar <strong>Git</strong> y conectarte por <strong>SSH</strong> a servidores (o convertir tu teléfono en uno).</li>\n<li>Controlar funciones del teléfono (batería, notificaciones, portapapeles, voz…) con <strong>Termux:API</strong>.</li>\n<li>Automatizar tareas y acceder rápido con <strong>widgets</strong>.</li>\n<li>Instalar <strong>Debian o Ubuntu</strong> completo con <code>proot-distro</code>.</li>\n</ul>\n\n<div class=\"tip\">\n💡 Este curso es perfecto para complementar <em>Consola de Comandos: Primeros Pasos</em> y <em>Bash desde Cero</em>: lo aprendido allí funciona igual aquí.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué Termux puede correr programas de Linux en un teléfono Android?","options":["Porque instala Windows por debajo","Porque Android está construido sobre el kernel Linux","Porque necesita root obligatoriamente","Porque emula un procesador de PC"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Instalar Termux bien (y evitar el error más común)","description":"De dónde bajarlo, qué complementos existen y por qué importa que sean de la misma fuente.","content":"\n<h2>Dónde instalarlo</h2>\n<p>El proyecto Termux recomienda instalarlo desde <strong>F-Droid</strong> (una tienda de aplicaciones libres) o desde las <strong>versiones oficiales en GitHub</strong> (<code>github.com/termux/termux-app</code>). Durante años, la versión de Google Play estuvo sin mantenimiento y tenía repositorios de paquetes obsoletos, lo que causaba errores como \"no se pueden instalar paquetes\". Por eso la recomendación general sigue siendo F-Droid o GitHub.</p>\n\n<div class=\"warn\">\n⚠️ <strong>El error más común:</strong> mezclar fuentes. Termux y sus complementos (Termux:API, Termux:Boot, Termux:Widget…) deben venir <strong>de la misma fuente</strong> (todos F-Droid, o todos GitHub). Si mezclas, Android los ve firmados por autores distintos y los complementos no funcionan.\n</div>\n\n<h2>Las aplicaciones de la familia</h2>\n<table>\n<tr><th>App</th><th>Para qué sirve</th></tr>\n<tr><td><strong>Termux</strong></td><td>La terminal principal (obligatoria).</td></tr>\n<tr><td>Termux:API</td><td>Permite que tus comandos usen funciones del teléfono (batería, notificaciones, sensores…).</td></tr>\n<tr><td>Termux:Widget</td><td>Widgets en la pantalla de inicio para ejecutar tus scripts con un toque.</td></tr>\n<tr><td>Termux:Boot</td><td>Ejecuta scripts cuando el teléfono se enciende.</td></tr>\n<tr><td>Termux:Styling</td><td>Colores y fuentes.</td></tr>\n</table>\n\n<h2>Requisitos y consejos</h2>\n<ul>\n<li>Necesitas una versión de Android razonablemente reciente (en general, Android 7 o superior para las versiones actuales); revisa la página del proyecto para tu caso.</li>\n<li>Con unos <strong>500 MB libres</strong> tienes para empezar; los paquetes ocupan espacio.</li>\n<li>La primera vez que abras Termux, espera a que termine de configurarse antes de escribir.</li>\n<li>Si el teléfono tiene \"optimización de batería\" agresiva (Xiaomi, Huawei, Samsung…), desactívala para Termux si vas a dejar procesos corriendo.</li>\n</ul>\n\n<div class=\"example\">\n<strong>Regla de oro para este curso:</strong> instala <em>solo</em> Termux al principio. Los complementos los instalarás más adelante, cuando los necesites, y siempre de la misma fuente.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué es importante instalar Termux y sus complementos de la misma fuente?","options":["Por estética","Porque si mezclas fuentes las firmas de las apps no coinciden y los complementos no funcionan","Porque F-Droid es más rápido","Porque Termux:API es de pago"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Primer arranque: tu casa dentro de Termux","description":"El prompt, la carpeta HOME, actualizar los paquetes y entender que Android no es una distro de PC.","content":"\n<h2>Actualiza antes de hacer cualquier cosa</h2>\n<p>Al abrir Termux verás un símbolo <code>$</code>: es el <strong>prompt</strong>, donde escribes comandos. Lo primero que se hace siempre:</p>\n<pre><code>pkg update && pkg upgrade</code></pre>\n<p><code>pkg update</code> descarga la lista más reciente de paquetes disponibles y <code>pkg upgrade</code> actualiza los que ya tienes. El <code>&amp;&amp;</code> significa \"y si eso salió bien, entonces ejecuta lo siguiente\". Si te pregunta algo (Y/n), responde <code>y</code>. Si tarda o falla, prueba con <code>termux-change-repo</code> para elegir un espejo (servidor) más cercano.</p>\n\n<h2>Dónde estás parado</h2>\n<table>\n<tr><th>Comando</th><th>Qué te dice</th></tr>\n<tr><td><code>pwd</code></td><td>Tu carpeta actual (al inicio: tu HOME, <code>/data/data/com.termux/files/home</code>).</td></tr>\n<tr><td><code>echo $PREFIX</code></td><td>Dónde están instalados los programas de Termux (<code>/data/data/com.termux/files/usr</code>).</td></tr>\n<tr><td><code>uname -o</code></td><td>El sistema operativo: dirá <strong>Android</strong>.</td></tr>\n<tr><td><code>whoami</code></td><td>Tu usuario (algo como <code>u0_a215</code>: un usuario de Android, no \"root\").</td></tr>\n</table>\n\n<h2>Una diferencia importante con Linux de PC</h2>\n<p>En un Linux normal existen rutas como <code>/bin</code>, <code>/usr</code> o <code>/etc</code>. En Termux <strong>todo vive dentro de su propia carpeta</strong>, y esas rutas están bajo <code>$PREFIX</code> (por ejemplo, <code>$PREFIX/bin</code> y <code>$PREFIX/etc</code>). Por eso, cuando siguas tutoriales de Linux para PC, a veces tendrás que traducir la ruta. Es normal: Android no es una distro de escritorio.</p>\n\n<div class=\"tip\">\n💡 Los comandos que aprendiste en el curso de Bash (<code>ls</code>, <code>cd</code>, <code>cat</code>, <code>grep</code>, pipes…) funcionan exactamente igual aquí.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Para qué sirve $PREFIX en Termux?","options":["Guarda tu contraseña","Indica dónde están instalados los programas y archivos de sistema de Termux (equivale a \"/usr\")","Es el nombre de tu teléfono","Es un comando para reiniciar"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"🖥️ Consola Interactiva: tu primer arranque en Termux","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Acabas de abrir Termux por primera vez. Vas a actualizarlo y a explorar dónde estás.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: tu primer arranque en Termux","intro":"Acabas de abrir Termux por primera vez. Vas a actualizarlo y a explorar dónde estás.","checkpoints":[{"instruction":"Actualiza la lista de paquetes y los paquetes instalados con: pkg update && pkg upgrade","placeholder":"pkg update && pkg upgrade","pattern":"^pkg\\s+(update|upgrade)(\\s+-y)?(\\s*&&\\s*pkg\\s+(update|upgrade)(\\s+-y)?)?\\s*$","hint":"Usa: pkg update && pkg upgrade","success":"Todo actualizado: siempre haz esto antes de instalar nada nuevo.","output":"Reading package lists... Done\nAll packages are up to date."},{"instruction":"Pregunta en qué sistema operativo estás con uname -o.","placeholder":"uname -o","pattern":"^uname\\s+-o\\s*$","hint":"Usa: uname -o","success":"Android: el kernel es Linux, pero el sistema es Android.","output":"Android"},{"instruction":"Descubre en qué carpeta estás con pwd.","placeholder":"pwd","pattern":"^pwd\\s*$","hint":"Usa: pwd","success":"Esa es tu carpeta personal (HOME) dentro de Termux.","output":"/data/data/com.termux/files/home"},{"instruction":"Descubre dónde se instalan los programas: echo $PREFIX","placeholder":"echo $PREFIX","pattern":"^echo\\s+[\"'']?\\$\\{?PREFIX\\}?[\"'']?\\s*$","hint":"Usa: echo $PREFIX","success":"Ahí vive todo lo que instalas con pkg.","output":"/data/data/com.termux/files/usr"}]},"id":3,"order":3},{"type":"text","title":"Moverte cómodo: teclas extra, gestos y sesiones","description":"La terminal en una pantalla táctil tiene trucos que hacen la diferencia.","content":"\n<h2>La fila de teclas extra</h2>\n<p>Debajo del teclado de tu teléfono, Termux muestra una fila con teclas que en un teclado táctil no existen: <code>ESC</code>, <code>TAB</code>, <code>CTRL</code>, <code>ALT</code>, flechas, <code>-</code> y <code>/</code>. Se usan tocándolas: por ejemplo, <code>CTRL</code> y luego <code>C</code> cancela un comando.</p>\n\n<h2>Combinaciones con las teclas de volumen</h2>\n<table>\n<tr><th>Combinación</th><th>Equivale a</th></tr>\n<tr><td>Volumen abajo + una tecla</td><td>CTRL + esa tecla (por ejemplo Volumen abajo + C = CTRL+C)</td></tr>\n<tr><td>Volumen arriba + W / A / S / D</td><td>Flechas arriba / izquierda / abajo / derecha</td></tr>\n<tr><td>Volumen arriba + Q</td><td>Mostrar u ocultar la fila de teclas extra</td></tr>\n</table>\n\n<h2>Gestos y menús</h2>\n<ul>\n<li><strong>Deslizar desde el borde izquierdo:</strong> abre el panel de <em>sesiones</em>: puedes tener varias terminales abiertas a la vez y cambiar entre ellas.</li>\n<li><strong>Mantener presionada la pantalla:</strong> menú para copiar, pegar y otras opciones.</li>\n<li><strong>Pellizcar con dos dedos:</strong> cambia el tamaño de la letra.</li>\n</ul>\n\n<h2>Atajos de terminal que valen oro</h2>\n<table>\n<tr><th>Atajo</th><th>Qué hace</th></tr>\n<tr><td>TAB</td><td>Autocompleta nombres de archivos y comandos. ¡Úsalo siempre!</td></tr>\n<tr><td>Flecha arriba</td><td>Recupera el comando anterior.</td></tr>\n<tr><td>CTRL + C</td><td>Cancela lo que se esté ejecutando.</td></tr>\n<tr><td>CTRL + L (o <code>clear</code>)</td><td>Limpia la pantalla.</td></tr>\n<tr><td>CTRL + D</td><td>Cierra la sesión actual.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Un teclado físico Bluetooth (o un teclado de PC conectado por OTG) convierte tu teléfono en una mini laptop para programar. Muchas personas usan Termux así.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué combinación equivale a CTRL+C (cancelar un comando) en el teclado táctil?","options":["Volumen arriba + C","Volumen abajo + C","Mantener presionado ESC","Deslizar desde la izquierda"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Instalar programas con pkg","description":"El gestor de paquetes de Termux: buscar, instalar, actualizar y quitar.","content":"\n<h2>Un gestor de paquetes, como en Linux de PC</h2>\n<p>En Termux no descargas instaladores: usas el gestor de paquetes <code>pkg</code>. Por debajo usa <strong>apt</strong> (el mismo de Debian y Ubuntu), pero con una capa más sencilla.</p>\n\n<table>\n<tr><th>Comando</th><th>Qué hace</th></tr>\n<tr><td><code>pkg search palabra</code></td><td>Busca paquetes.</td></tr>\n<tr><td><code>pkg install nombre</code></td><td>Instala uno (o varios separados por espacio).</td></tr>\n<tr><td><code>pkg list-installed</code></td><td>Lista lo instalado.</td></tr>\n<tr><td><code>pkg upgrade</code></td><td>Actualiza todo.</td></tr>\n<tr><td><code>pkg uninstall nombre</code></td><td>Desinstala.</td></tr>\n<tr><td><code>pkg show nombre</code></td><td>Muestra información de un paquete.</td></tr>\n</table>\n\n<h2>Un kit inicial recomendado</h2>\n<table>\n<tr><th>Paquete</th><th>Para qué</th></tr>\n<tr><td><code>nano</code></td><td>Editor de texto fácil.</td></tr>\n<tr><td><code>vim</code></td><td>Editor potente (curva de aprendizaje mayor).</td></tr>\n<tr><td><code>git</code></td><td>Control de versiones.</td></tr>\n<tr><td><code>python</code></td><td>El lenguaje Python.</td></tr>\n<tr><td><code>curl</code>, <code>wget</code></td><td>Descargar cosas de internet.</td></tr>\n<tr><td><code>openssh</code></td><td>Conexiones SSH.</td></tr>\n<tr><td><code>htop</code></td><td>Ver qué procesos usan recursos.</td></tr>\n<tr><td><code>tmux</code></td><td>Varias terminales en una pantalla, y sesiones que sobreviven.</td></tr>\n<tr><td><code>neofetch</code> / <code>fastfetch</code></td><td>Resumen bonito del sistema.</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Instala solo desde los repositorios oficiales de Termux con <code>pkg</code>. Si un tutorial te pide pegar un comando que descarga y ejecuta un script desconocido, <strong>desconfía</strong>: tendría acceso a todo lo que Termux puede ver.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué comando instala Git en Termux?","options":["install git","pkg install git","termux git","sudo git"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"🖥️ Consola Interactiva: instala tu kit de herramientas","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a buscar, instalar y comprobar programas con pkg.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: instala tu kit de herramientas","intro":"Vas a buscar, instalar y comprobar programas con pkg.","checkpoints":[{"instruction":"Busca paquetes relacionados con python usando pkg search.","placeholder":"pkg search python","pattern":"^pkg\\s+search\\s+python\\s*$","hint":"Usa: pkg search python","success":"Así se descubren paquetes sin salir de la terminal.","output":"python/stable 3.12.x aarch64\n  Python 3 programming language intended to enable clear programs\npython-pip/stable 24.x all\n  The PyPA recommended tool for installing Python packages"},{"instruction":"Instala nano y git en un solo comando: pkg install nano git","placeholder":"pkg install nano git","pattern":"^pkg\\s+install\\s+(-y\\s+)?(nano\\s+git|git\\s+nano)\\s*$","hint":"Usa: pkg install nano git","success":"Dos paquetes con un solo comando.","output":"Setting up nano ...\nSetting up git ..."},{"instruction":"Comprueba que git quedó instalado con git --version.","placeholder":"git --version","pattern":"^git\\s+--version\\s*$","hint":"Usa: git --version","success":"Listo: Git funciona en tu teléfono.","output":"git version 2.4x.x"},{"instruction":"Ahora lista lo instalado y filtra por \"nano\" usando un pipe: pkg list-installed | grep nano","placeholder":"pkg list-installed | grep nano","pattern":"^pkg\\s+list-installed\\s*\\|\\s*grep\\s+[\"'']?nano[\"'']?\\s*$","hint":"Usa: pkg list-installed | grep nano","success":"Combinaste dos programas con un pipe, como en la filosofía Unix.","output":"nano/stable,now 8.x aarch64 [installed]"}]},"id":6,"order":6},{"type":"text","title":"Acceso a tus archivos y almacenamiento del teléfono","description":"Cómo Termux ve tus descargas, fotos y documentos.","content":"\n<h2>Termux vive en una \"jaula\"</h2>\n<p>Por seguridad, Android aísla cada app: Termux no puede ver tus fotos, descargas o documentos a menos que se lo permitas. Para eso existe el comando:</p>\n<pre><code>termux-setup-storage</code></pre>\n<p>Te aparecerá una ventana de Android pidiendo permiso de almacenamiento. Acepta, y Termux creará la carpeta <code>~/storage</code> con accesos directos (enlaces) a las carpetas del teléfono.</p>\n\n<table>\n<tr><th>Ruta</th><th>Apunta a</th></tr>\n<tr><td><code>~/storage/shared</code></td><td>Todo el almacenamiento compartido del teléfono</td></tr>\n<tr><td><code>~/storage/downloads</code></td><td>La carpeta Descargas</td></tr>\n<tr><td><code>~/storage/dcim</code></td><td>Fotos de la cámara</td></tr>\n<tr><td><code>~/storage/pictures</code></td><td>Imágenes</td></tr>\n<tr><td><code>~/storage/music</code>, <code>~/storage/movies</code></td><td>Música y videos</td></tr>\n</table>\n\n<h2>Dos mundos de archivos</h2>\n<ul>\n<li><strong>Dentro de Termux</strong> (tu HOME): rápido, con permisos de Linux (puedes usar <code>chmod</code>), pero <em>otras apps no lo ven</em>.</li>\n<li><strong>Almacenamiento compartido</strong> (<code>~/storage/...</code>): lo ven otras apps (galería, gestor de archivos), pero tiene limitaciones (por ejemplo, no puedes marcar archivos como ejecutables allí).</li>\n</ul>\n<p>Por eso el patrón habitual es: trabajar dentro de tu HOME y <strong>copiar</strong> a <code>~/storage</code> lo que quieras compartir o respaldar.</p>\n\n<div class=\"example\">\n<strong>Ejemplo real:</strong> cuando descargas un archivo desde el navegador queda en Descargas. Con <code>cp ~/storage/downloads/archivo.zip ~</code> lo copias a tu HOME para trabajar con él, y con <code>cp resultado.txt ~/storage/downloads/</code> lo devuelves para que lo vea el resto de tu teléfono.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Para qué sirve el comando termux-setup-storage?","options":["Para borrar archivos del teléfono","Para dar permiso a Termux de ver el almacenamiento compartido y crear accesos directos en ~/storage","Para formatear la memoria","Para instalar más espacio"],"correctIndex":1},"id":7,"order":7},{"type":"text","title":"🖥️ Consola Interactiva: accede a tus descargas","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a dar permiso de almacenamiento y a trabajar con un archivo que descargaste desde el navegador.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: accede a tus descargas","intro":"Vas a dar permiso de almacenamiento y a trabajar con un archivo que descargaste desde el navegador.","checkpoints":[{"instruction":"Da permiso de almacenamiento a Termux.","placeholder":"termux-setup-storage","pattern":"^termux-setup-storage\\s*$","hint":"Usa: termux-setup-storage","success":"Android te habría pedido permiso; ahora existe la carpeta ~/storage."},{"instruction":"Lista los accesos directos creados en ~/storage.","placeholder":"ls ~/storage","pattern":"^ls\\s+(~|\\$HOME)/storage/?\\s*$","hint":"Usa: ls ~/storage","success":"Estos son los puentes hacia el resto de tu teléfono.","output":"dcim  downloads  movies  music  pictures  shared"},{"instruction":"Copia el archivo notas.txt de Descargas a tu carpeta personal (~).","placeholder":"cp ~/storage/downloads/notas.txt ~","pattern":"^cp\\s+(~|\\$HOME)/storage/downloads/notas\\.txt\\s+(~|\\$HOME|\\./?)/?\\s*$","hint":"Usa: cp ~/storage/downloads/notas.txt ~","success":"Copiado. Ahora puedes trabajar con el archivo dentro de Termux."},{"instruction":"Confirma que llegó: ls ~","placeholder":"ls ~","pattern":"^ls\\s+(~|\\$HOME)/?\\s*$","hint":"Usa: ls ~","success":"Ahí está tu archivo en tu carpeta personal.","output":"notas.txt  storage"}]},"id":8,"order":8},{"type":"text","title":"Editar y ejecutar tus primeros scripts","description":"nano, permisos de ejecución y un script que hace algo útil.","content":"\n<h2>Un editor en la terminal: nano</h2>\n<p>Instálalo con <code>pkg install nano</code> y ábrelo con <code>nano archivo.txt</code>. En la parte inferior verás los atajos (el símbolo <code>^</code> significa CTRL): <code>CTRL+O</code> guarda, <code>CTRL+X</code> sale. Para escribir texto sin editor, también puedes usar redirección:</p>\n<pre><code>echo \"hola\" &gt; saludo.txt      # crea (o sobrescribe) el archivo\necho \"otra línea\" &gt;&gt; saludo.txt  # agrega al final</code></pre>\n\n<h2>Tu primer script</h2>\n<p>Un <strong>script</strong> es un archivo de texto con comandos que se ejecutan en orden. Ejemplo (archivo <code>hola.sh</code>):</p>\n<pre><code>#!/data/data/com.termux/files/usr/bin/bash\necho \"Hola desde Termux\"\ndate</code></pre>\n<p>La primera línea (<em>shebang</em>) le dice al sistema qué programa debe interpretarlo. En Termux la ruta de bash es distinta a la de Linux de PC (<code>/bin/bash</code>), pero Termux incluye el comando <code>termux-fix-shebang archivo.sh</code> para corregir scripts descargados de otros lados.</p>\n\n<h2>Permiso de ejecución</h2>\n<p>Un archivo nuevo no se puede ejecutar todavía. Hay que dárselo:</p>\n<pre><code>chmod +x hola.sh\n./hola.sh</code></pre>\n<p>El <code>./</code> significa \"el archivo de esta carpeta\". Si prefieres no cambiar permisos, también funciona <code>bash hola.sh</code>.</p>\n\n<div class=\"tip\">\n💡 Tus scripts deben vivir en tu HOME, no en <code>~/storage</code>: el almacenamiento compartido no admite permisos de ejecución.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace chmod +x hola.sh?","options":["Borra el archivo","Le da permiso de ejecución al archivo","Lo copia a la nube","Lo abre en el editor"],"correctIndex":1},"id":9,"order":9},{"type":"text","title":"🖥️ Consola Interactiva: crea y ejecuta un script","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a crear un script sin editor (con echo y redirección), darle permisos y ejecutarlo.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: crea y ejecuta un script","intro":"Vas a crear un script sin editor (con echo y redirección), darle permisos y ejecutarlo.","checkpoints":[{"instruction":"Crea el archivo hola.sh con un comando echo dentro: echo ''echo \"Hola desde Termux\"'' > hola.sh","placeholder":"echo ''echo \"Hola desde Termux\"'' > hola.sh","pattern":"^echo\\s+.+>\\s*hola\\.sh\\s*$","hint":"Usa: echo ''echo \"Hola desde Termux\"'' > hola.sh (el > manda el texto al archivo)","success":"Archivo creado. El símbolo > redirige la salida de echo hacia hola.sh."},{"instruction":"Dale permiso de ejecución.","placeholder":"chmod +x hola.sh","pattern":"^chmod\\s+(\\+x|755|u\\+x)\\s+hola\\.sh\\s*$","hint":"Usa: chmod +x hola.sh","success":"Ahora el archivo es ejecutable."},{"instruction":"Ejecútalo con ./hola.sh","placeholder":"./hola.sh","pattern":"^(\\./hola\\.sh|bash\\s+hola\\.sh)\\s*$","hint":"Usa: ./hola.sh","success":"Tu primer script en el teléfono.","output":"Hola desde Termux"}]},"id":10,"order":10},{"type":"text","title":"Python y programación desde el teléfono","description":"Instala Python, corre programas, usa pip y sirve archivos por la red local.","content":"\n<h2>Python en un comando</h2>\n<pre><code>pkg install python\npython --version\npython hola.py</code></pre>\n<p>Con Python ya puedes seguir cualquier curso de programación desde tu teléfono. Crea un archivo, por ejemplo con <code>nano hola.py</code>, y escribe <code>print(\"Hola, mundo\")</code>.</p>\n\n<h2>Instalar librerías con pip</h2>\n<pre><code>pip install requests</code></pre>\n<p>Funciona para librerías \"puras\" de Python. Las que tienen partes compiladas (por ejemplo <em>numpy</em>, <em>pandas</em>) a veces fallan al instalarse con pip en Android; para esas, Termux suele tener paquetes ya compilados: <code>pkg install python-numpy</code>. Antes de pelear con un error de compilación, busca con <code>pkg search</code> si ya existe.</p>\n\n<h2>Otros lenguajes</h2>\n<table>\n<tr><th>Lenguaje</th><th>Instalación</th></tr>\n<tr><td>Node.js (JavaScript)</td><td><code>pkg install nodejs</code></td></tr>\n<tr><td>C / C++</td><td><code>pkg install clang</code></td></tr>\n<tr><td>Rust</td><td><code>pkg install rust</code></td></tr>\n<tr><td>Go</td><td><code>pkg install golang</code></td></tr>\n<tr><td>PHP, Ruby, Lua…</td><td><code>pkg install php</code> / <code>ruby</code> / <code>lua54</code></td></tr>\n</table>\n\n<h2>Un servidor web en un comando</h2>\n<p>Python trae un servidor web de una línea. Desde una carpeta cualquiera:</p>\n<pre><code>python -m http.server 8080</code></pre>\n<p>Ahora esa carpeta se puede ver desde el navegador del teléfono en <code>http://localhost:8080</code>, y desde otro dispositivo de tu misma red Wi-Fi usando la IP del teléfono. Para detenerlo: <code>CTRL+C</code>.</p>\n\n<div class=\"warn\">\n⚠️ Ese servidor comparte <strong>todo lo que haya en la carpeta</strong>, con cualquiera de la red. Úsalo en tu Wi-Fi de casa, con una carpeta que solo contenga lo que quieras compartir, y no en redes públicas.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace \"python -m http.server 8080\"?","options":["Instala Python","Levanta un servidor web sencillo que comparte la carpeta actual en el puerto 8080","Borra la carpeta","Sube el código a GitHub"],"correctIndex":1},"id":11,"order":11},{"type":"text","title":"🖥️ Consola Interactiva: Python y tu servidor web","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a instalar Python, ejecutar una línea y compartir una carpeta por la red.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: Python y tu servidor web","intro":"Vas a instalar Python, ejecutar una línea y compartir una carpeta por la red.","checkpoints":[{"instruction":"Instala Python con pkg.","placeholder":"pkg install python","pattern":"^pkg\\s+install\\s+(-y\\s+)?python\\s*$","hint":"Usa: pkg install python","success":"Python instalado.","output":"Setting up python ..."},{"instruction":"Ejecuta una línea de Python: python -c \"print(2+2)\"","placeholder":"python -c \"print(2+2)\"","pattern":"^python3?\\s+-c\\s+[\"'']print\\(\\s*2\\s*\\+\\s*2\\s*\\)[\"'']\\s*$","hint":"Usa: python -c \"print(2+2)\"","success":"Python respondió. Ya puedes programar desde tu teléfono.","output":"4"},{"instruction":"Comparte la carpeta actual por la red con: python -m http.server 8080","placeholder":"python -m http.server 8080","pattern":"^python3?\\s+-m\\s+http\\.server(\\s+8080)?\\s*$","hint":"Usa: python -m http.server 8080","success":"Servidor activo. Para pararlo, CTRL+C.","output":"Serving HTTP on 0.0.0.0 port 8080 (http://0.0.0.0:8080/) ..."}]},"id":12,"order":12},{"type":"text","title":"Git, GitHub y llaves SSH desde el teléfono","description":"Clona, edita y sube código sin computadora.","content":"\n<h2>Configurar Git</h2>\n<pre><code>pkg install git\ngit config --global user.name \"Tu Nombre\"\ngit config --global user.email \"tu@correo.com\"</code></pre>\n<p>Si quieres el curso completo, la escuela tiene <em>Git y GitHub: de Cero a Experto</em>; todo lo que allí aprendes funciona en Termux.</p>\n\n<h2>Llaves SSH: entrar sin contraseña</h2>\n<p>En vez de escribir tu contraseña (o un token) cada vez que subes código a GitHub, puedes usar un <strong>par de llaves SSH</strong>: una <em>privada</em> (que jamás compartes) y una <em>pública</em> (que sí entregas).</p>\n<pre><code>pkg install openssh\nssh-keygen -t ed25519 -C \"tu@correo.com\"\ncat ~/.ssh/id_ed25519.pub</code></pre>\n<p>Copia lo que muestre el último comando y pégalo en GitHub: <em>Settings → SSH and GPG keys → New SSH key</em>. Luego prueba con <code>ssh -T git@github.com</code>, y clona repositorios con la URL de tipo <code>git@github.com:usuario/repo.git</code>.</p>\n\n<div class=\"warn\">\n⚠️ <strong>La llave privada</strong> (<code>id_ed25519</code>, sin <code>.pub</code>) es como tu contraseña: nunca la pegues en chats, foros, ni la subas a un repositorio. La pública (<code>.pub</code>) sí puede compartirse.\n</div>\n\n<h2>Flujo típico desde el teléfono</h2>\n<ol>\n<li><code>git clone git@github.com:usuario/repo.git</code></li>\n<li>Editar con <code>nano</code> o <code>vim</code>.</li>\n<li><code>git add . &amp;&amp; git commit -m \"mensaje\"</code></li>\n<li><code>git push</code></li>\n</ol>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál de estas llaves SSH nunca debes compartir?","options":["La pública (.pub)","La privada (sin .pub)","Ambas se pueden compartir","Ninguna existe en Termux"],"correctIndex":1},"id":13,"order":13},{"type":"text","title":"🖥️ Consola Interactiva: configura Git y crea tu llave SSH","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a presentarte ante Git y generar tu par de llaves.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: configura Git y crea tu llave SSH","intro":"Vas a presentarte ante Git y generar tu par de llaves.","checkpoints":[{"instruction":"Configura tu nombre en Git: git config --global user.name \"Ada Torres\"","placeholder":"git config --global user.name \"Ada Torres\"","pattern":"^git\\s+config\\s+--global\\s+user\\.name\\s+.+$","hint":"Usa: git config --global user.name \"Ada Torres\"","success":"Git ya sabe quién eres."},{"instruction":"Genera una llave SSH moderna con: ssh-keygen -t ed25519","placeholder":"ssh-keygen -t ed25519","pattern":"^ssh-keygen\\s+-t\\s+ed25519(\\s+-C\\s+.+)?\\s*$","hint":"Usa: ssh-keygen -t ed25519","success":"Se creó el par de llaves en ~/.ssh: id_ed25519 (privada) e id_ed25519.pub (pública).","output":"Generating public/private ed25519 key pair.\nYour public key has been saved in /data/data/com.termux/files/home/.ssh/id_ed25519.pub"},{"instruction":"Muestra tu llave pública (la que sí se comparte): cat ~/.ssh/id_ed25519.pub","placeholder":"cat ~/.ssh/id_ed25519.pub","pattern":"^cat\\s+(~|\\$HOME)/\\.ssh/id_ed25519\\.pub\\s*$","hint":"Usa: cat ~/.ssh/id_ed25519.pub","success":"Esta línea es la que pegas en GitHub. Nunca muestres la privada.","output":"ssh-ed25519 AAAAC3Nz...ejemplo... ada@ejemplo.com"}]},"id":14,"order":14},{"type":"text","title":"SSH: conecta tu teléfono con tu computadora (y al revés)","description":"Usar servidores remotos desde el teléfono, o controlar el teléfono desde tu PC.","content":"\n<h2>SSH: la puerta segura de la terminal</h2>\n<p><strong>SSH</strong> (Secure Shell) te permite abrir una terminal en <em>otra</em> máquina por la red, con la conexión cifrada. Es la herramienta diaria de quien administra servidores. Con Termux puedes hacer las dos direcciones.</p>\n\n<h2>Dirección 1: tu teléfono como cliente</h2>\n<pre><code>ssh usuario@direccion-del-servidor</code></pre>\n<p>Así administras un servidor (o una Raspberry Pi) desde cualquier lugar, sin computadora.</p>\n\n<h2>Dirección 2: tu teléfono como servidor</h2>\n<p>También puedes controlar el teléfono desde tu PC (¡sin cables!):</p>\n<ol>\n<li>En Termux: <code>pkg install openssh</code></li>\n<li>Crea una contraseña: <code>passwd</code></li>\n<li>Descubre tu usuario: <code>whoami</code> (algo como <code>u0_a215</code>).</li>\n<li>Arranca el servidor: <code>sshd</code></li>\n<li>Descubre la IP del teléfono en tu Wi-Fi (por ejemplo con <code>ifconfig</code> del paquete <code>net-tools</code>, o desde los ajustes de Wi-Fi).</li>\n<li>Desde la PC: <code>ssh -p 8022 u0_a215@192.168.1.50</code> (con tus datos).</li>\n</ol>\n<div class=\"warn\">\n⚠️ En Termux el servidor SSH escucha en el <strong>puerto 8022</strong>, no en el 22 (Android no permite a una app normal usar puertos bajos). Por eso se usa <code>-p 8022</code>.\n</div>\n\n<h2>Buenas prácticas</h2>\n<ul>\n<li>Usa una <strong>contraseña larga</strong> o, mejor, <strong>llaves SSH</strong> (clase anterior).</li>\n<li>Activa <code>sshd</code> solo cuando lo necesites, en tu red de confianza, y ciérralo después (<code>pkill sshd</code>).</li>\n<li>Nunca expongas tu teléfono a internet con SSH abierto sin saber lo que haces.</li>\n<li>Solo te conectas a máquinas <strong>tuyas o con permiso</strong>.</li>\n</ul>\n","exercises":[],"resources":[],"quiz":{"question":"¿En qué puerto escucha el servidor SSH de Termux?","options":["22","8022","80","443"],"correctIndex":1},"id":15,"order":15},{"type":"text","title":"🖥️ Consola Interactiva: convierte tu teléfono en servidor SSH","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a preparar tu teléfono para recibir conexiones SSH desde tu computadora, dentro de tu red de casa.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: convierte tu teléfono en servidor SSH","intro":"Vas a preparar tu teléfono para recibir conexiones SSH desde tu computadora, dentro de tu red de casa.","checkpoints":[{"instruction":"Instala el servidor y cliente SSH: pkg install openssh","placeholder":"pkg install openssh","pattern":"^pkg\\s+install\\s+(-y\\s+)?openssh\\s*$","hint":"Usa: pkg install openssh","success":"OpenSSH listo.","output":"Setting up openssh ..."},{"instruction":"Crea una contraseña para poder conectarte: passwd","placeholder":"passwd","pattern":"^passwd\\s*$","hint":"Usa: passwd","success":"Te habría pedido escribir la nueva contraseña dos veces.","output":"New password:\nRetype new password:\nNew password was successfully set."},{"instruction":"Descubre tu nombre de usuario en Termux: whoami","placeholder":"whoami","pattern":"^whoami\\s*$","hint":"Usa: whoami","success":"Ese es tu usuario (no es root): lo usarás para conectarte desde la PC.","output":"u0_a215"},{"instruction":"Arranca el servidor SSH: sshd","placeholder":"sshd","pattern":"^sshd\\s*$","hint":"Usa: sshd","success":"Servidor activo en el puerto 8022. Desde tu PC: ssh -p 8022 u0_a215@IP-DEL-TELEFONO. Para apagarlo: pkill sshd."}]},"id":16,"order":16},{"type":"text","title":"Termux:API — controla el teléfono desde la terminal","description":"Batería, notificaciones, portapapeles, voz, linterna, ubicación…","content":"\n<h2>Dos piezas que van juntas</h2>\n<p>Para que tus comandos hablen con las funciones del teléfono necesitas <strong>las dos partes</strong>:</p>\n<ol>\n<li>La <strong>app</strong> Termux:API (de la misma fuente que Termux).</li>\n<li>El <strong>paquete</strong> en Termux: <code>pkg install termux-api</code></li>\n</ol>\n\n<h2>Algunos comandos</h2>\n<table>\n<tr><th>Comando</th><th>Qué hace</th></tr>\n<tr><td><code>termux-battery-status</code></td><td>Estado de la batería en formato JSON.</td></tr>\n<tr><td><code>termux-toast \"Hola\"</code></td><td>Muestra un mensajito flotante.</td></tr>\n<tr><td><code>termux-notification --title \"Aviso\" --content \"Listo\"</code></td><td>Crea una notificación.</td></tr>\n<tr><td><code>termux-vibrate -d 300</code></td><td>Vibra 300 milisegundos.</td></tr>\n<tr><td><code>termux-clipboard-get</code> / <code>-set</code></td><td>Lee o escribe el portapapeles.</td></tr>\n<tr><td><code>termux-tts-speak \"Hola\"</code></td><td>El teléfono lee el texto en voz alta.</td></tr>\n<tr><td><code>termux-torch on</code></td><td>Enciende la linterna.</td></tr>\n<tr><td><code>termux-location</code></td><td>Tu ubicación (requiere permisos).</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Cada función sensible (ubicación, cámara, micrófono, contactos, SMS…) requiere que <strong>tú</strong> concedas el permiso a Termux:API en los ajustes de Android. Concede solo lo que vayas a usar, y recuerda que cualquier script que ejecutes podrá usar esos permisos.\n</div>\n\n<h2>Combinar con pipes y scripts</h2>\n<p>La salida de <code>termux-battery-status</code> es JSON. Si instalas <code>jq</code> (<code>pkg install jq</code>) puedes extraer solo un dato:</p>\n<pre><code>termux-battery-status | jq .percentage</code></pre>\n<p>Y con eso puedes crear, por ejemplo, un script que te avise por notificación cuando la batería baje del 20%.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué necesitas para usar comandos como termux-battery-status?","options":["Solo el paquete termux-api","La app Termux:API y el paquete termux-api (más los permisos de Android correspondientes)","Root","Una cuenta de Google"],"correctIndex":1},"id":17,"order":17},{"type":"text","title":"🖥️ Consola Interactiva: habla con tu teléfono","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Ya tienes instalada la app Termux:API. Falta el paquete y probar algunos comandos.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: habla con tu teléfono","intro":"Ya tienes instalada la app Termux:API. Falta el paquete y probar algunos comandos.","checkpoints":[{"instruction":"Instala el paquete que conecta la terminal con la app: pkg install termux-api","placeholder":"pkg install termux-api","pattern":"^pkg\\s+install\\s+(-y\\s+)?termux-api\\s*$","hint":"Usa: pkg install termux-api","success":"Instalado.","output":"Setting up termux-api ..."},{"instruction":"Consulta la batería: termux-battery-status","placeholder":"termux-battery-status","pattern":"^termux-battery-status\\s*$","hint":"Usa: termux-battery-status","success":"JSON con el porcentaje, si está cargando y la temperatura.","output":"{\n  \"percentage\": 78,\n  \"status\": \"DISCHARGING\",\n  \"plugged\": \"UNPLUGGED\"\n}"},{"instruction":"Muestra un mensaje flotante: termux-toast \"Hola desde la terminal\"","placeholder":"termux-toast \"Hola desde la terminal\"","pattern":"^termux-toast\\s+.+$","hint":"Usa: termux-toast \"Hola desde la terminal\"","success":"En tu teléfono habría aparecido el mensaje sobre la pantalla."},{"instruction":"Haz que el teléfono hable: termux-tts-speak \"Termux funciona\"","placeholder":"termux-tts-speak \"Termux funciona\"","pattern":"^termux-tts-speak\\s+.+$","hint":"Usa: termux-tts-speak \"Termux funciona\"","success":"Y tu teléfono lo habría dicho en voz alta."}]},"id":18,"order":18},{"type":"text","title":"Automatiza: scripts, widgets, tareas y arranque","description":"Que tu teléfono haga cosas por ti sin que las pidas cada vez.","content":"\n<h2>Termux:Widget — un toque y listo</h2>\n<p>Con la app <strong>Termux:Widget</strong> puedes poner un widget en tu pantalla de inicio que lista los scripts de la carpeta <code>~/.shortcuts</code>. Un toque, y se ejecuta:</p>\n<pre><code>mkdir -p ~/.shortcuts\necho ''termux-notification --title \"Respaldo\" --content \"Hecho\"'' &gt; ~/.shortcuts/respaldo.sh\nchmod +x ~/.shortcuts/respaldo.sh</code></pre>\n\n<h2>Termux:Boot — al encender el teléfono</h2>\n<p>Con <strong>Termux:Boot</strong> instalada (y abierta una vez), cualquier script en <code>~/.termux/boot/</code> se ejecuta cuando el teléfono arranca. Sirve para levantar servicios (por ejemplo, un <code>sshd</code> o un servidor propio).</p>\n\n<h2>Tareas programadas</h2>\n<ul>\n<li><code>pkg install cronie</code> y <code>crond</code>: el clásico <strong>cron</strong> de Linux, para tareas repetidas.</li>\n<li><code>termux-job-scheduler</code> (del paquete termux-api): usa el planificador de Android, más amigable con la batería.</li>\n</ul>\n\n<h2>Que Android no mate tus procesos</h2>\n<p>Android es agresivo con la batería y puede cerrar procesos en segundo plano. Para tareas largas:</p>\n<ul>\n<li>Usa <code>termux-wake-lock</code> para que el teléfono no \"duerma\" Termux (y <code>termux-wake-unlock</code> al terminar).</li>\n<li>Desactiva la optimización de batería para Termux en los ajustes de Android.</li>\n<li>En versiones recientes de Android (12 en adelante), el sistema puede terminar procesos \"fantasma\" en segundo plano. Si te pasa, busca la documentación actual del proyecto para tu versión.</li>\n<li>Usa <code>tmux</code> para no perder tu sesión si la app se cierra.</li>\n</ul>\n\n<div class=\"example\">\n<strong>Idea de proyecto:</strong> un script que cada mañana consulta el clima con <code>curl</code>, y te lo lee en voz alta con <code>termux-tts-speak</code>. Todo lo que necesitas ya lo viste en este curso.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Dónde se guardan los scripts que aparecen en el widget de Termux:Widget?","options":["En ~/Downloads","En ~/.shortcuts","En /etc","En la tarjeta SD, obligatoriamente"],"correctIndex":1},"id":19,"order":19},{"type":"text","title":"🖥️ Consola Interactiva: crea tu primer atajo","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a crear un script para el widget de inicio que te avisa con una notificación.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: crea tu primer atajo","intro":"Vas a crear un script para el widget de inicio que te avisa con una notificación.","checkpoints":[{"instruction":"Crea la carpeta de atajos: mkdir -p ~/.shortcuts","placeholder":"mkdir -p ~/.shortcuts","pattern":"^mkdir\\s+(-p\\s+)?(~|\\$HOME)/\\.shortcuts/?\\s*$","hint":"Usa: mkdir -p ~/.shortcuts","success":"Carpeta creada."},{"instruction":"Crea el script: echo ''termux-toast \"Atajo listo\"'' > ~/.shortcuts/prueba.sh","placeholder":"echo ''termux-toast \"Atajo listo\"'' > ~/.shortcuts/prueba.sh","pattern":"^echo\\s+.+>\\s*(~|\\$HOME)/\\.shortcuts/prueba\\.sh\\s*$","hint":"Usa: echo ''termux-toast \"Atajo listo\"'' > ~/.shortcuts/prueba.sh","success":"Script creado dentro de la carpeta de atajos."},{"instruction":"Dale permiso de ejecución: chmod +x ~/.shortcuts/prueba.sh","placeholder":"chmod +x ~/.shortcuts/prueba.sh","pattern":"^chmod\\s+(\\+x|755)\\s+(~|\\$HOME)/\\.shortcuts/prueba\\.sh\\s*$","hint":"Usa: chmod +x ~/.shortcuts/prueba.sh","success":"Listo. Al añadir el widget de Termux:Widget a tu pantalla de inicio, \"prueba.sh\" aparecería en la lista."}]},"id":20,"order":20},{"type":"text","title":"proot-distro: una distro Linux completa dentro de Termux","description":"Debian, Ubuntu, Arch o Alpine en tu teléfono, sin root.","content":"\n<h2>¿Para qué?</h2>\n<p>Termux ya es muy completo, pero a veces necesitas un Linux \"normal\" (con <code>apt</code>, con rutas como <code>/etc</code>, y programas compilados para glibc). Para eso existe <strong>proot-distro</strong>: instala una distribución completa dentro de una carpeta de Termux y te deja \"entrar\" en ella.</p>\n\n<h2>Cómo funciona</h2>\n<p><strong>proot</strong> usa una técnica que engaña a los programas haciéndoles creer que están en la raíz del sistema (<code>/</code>) y que eres <em>root</em>, aunque en realidad todo ocurre dentro de la carpeta de Termux y sin privilegios reales de Android. Es seguro (no modifica el sistema) pero un poco más lento que Termux nativo.</p>\n\n<pre><code>pkg install proot-distro\nproot-distro list\nproot-distro install debian\nproot-distro login debian</code></pre>\n\n<p>Al entrar verás un prompt de Debian real. Ahí puedes usar <code>apt update</code>, <code>apt install</code>… igual que en un servidor Debian. Para salir, escribe <code>exit</code>.</p>\n\n<h2>Distros disponibles</h2>\n<table>\n<tr><th>Nombre</th><th>Familia</th><th>Ideal para</th></tr>\n<tr><td>debian</td><td>Debian</td><td>Estabilidad y compatibilidad general</td></tr>\n<tr><td>ubuntu</td><td>Debian</td><td>Seguir tutoriales pensados para Ubuntu</td></tr>\n<tr><td>alpine</td><td>Alpine</td><td>Ligereza (muy poco espacio)</td></tr>\n<tr><td>archlinux</td><td>Arch</td><td>Practicar con pacman y el estilo Arch</td></tr>\n</table>\n<p>Otras existen también; <code>proot-distro list</code> te muestra las que tu versión ofrece.</p>\n\n<h2>Límites</h2>\n<ul>\n<li>No tiene todas las funciones de un Linux \"de verdad\" (por ejemplo, no se pueden usar servicios de <code>systemd</code> ni montar discos).</li>\n<li>Las apps con interfaz gráfica requieren configuración extra (servidor VNC o X11); no es lo primero que hay que intentar.</li>\n<li>Ocupa bastante espacio (cientos de MB).</li>\n</ul>\n\n<div class=\"tip\">\n💡 Es una gran forma de <strong>practicar administración de Linux</strong> (usuarios, permisos, paquetes) sin instalar nada en tu PC ni arriesgar tu teléfono: si algo sale mal, borras la distro con <code>proot-distro remove debian</code> y empiezas de nuevo.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué te permite hacer proot-distro?","options":["Convertir tu teléfono en root","Instalar y usar una distribución Linux completa (Debian, Ubuntu…) dentro de Termux, sin root","Reemplazar Android por Linux","Descargar apps de Google Play"],"correctIndex":1},"id":21,"order":21},{"type":"text","title":"🖥️ Consola Interactiva: instala Debian dentro de Termux","description":"Practica en una consola interactiva simulada — sin arriesgar nada real.","content":"\n<h2>🖥️ Esta clase es 100% práctica</h2>\n<p>Vas a usar una <strong>consola interactiva simulada</strong> — no toca tu computadora ni tu teléfono, pero funciona igual para aprender: escribe exactamente el comando que se te pide en cada paso y presiona <strong>Ejecutar</strong> (o Enter). Si está bien, avanzas al siguiente paso.</p>\n<div class=\"tip\">\n💡 Si te equivocas, te da una pista — no hay límite de intentos. La idea es que el comando se te quede en los dedos, no solo en la cabeza. Cuando termines, prueba lo mismo en una terminal real (o en el <strong>Laboratorio de terminales</strong> de la Academia de Linux).\n</div>\n<p>Vas a instalar y entrar a una distro Debian completa en tu teléfono.</p>\n","exercises":[],"resources":[],"terminalSim":{"title":"Simulador: instala Debian dentro de Termux","intro":"Vas a instalar y entrar a una distro Debian completa en tu teléfono.","checkpoints":[{"instruction":"Instala proot-distro: pkg install proot-distro","placeholder":"pkg install proot-distro","pattern":"^pkg\\s+install\\s+(-y\\s+)?proot-distro\\s*$","hint":"Usa: pkg install proot-distro","success":"Instalado.","output":"Setting up proot-distro ..."},{"instruction":"Mira las distribuciones disponibles: proot-distro list","placeholder":"proot-distro list","pattern":"^proot-distro\\s+list\\s*$","hint":"Usa: proot-distro list","success":"Estas son algunas de las opciones.","output":"Supported distributions:\n  * Alpine Linux (alpine)\n  * Arch Linux (archlinux)\n  * Debian (debian)\n  * Ubuntu (ubuntu)\n  ..."},{"instruction":"Instala Debian: proot-distro install debian","placeholder":"proot-distro install debian","pattern":"^proot-distro\\s+install\\s+debian\\s*$","hint":"Usa: proot-distro install debian","success":"Debian descargada y lista (esto puede tardar unos minutos en un teléfono real).","output":"[*] Installing Debian...\n[*] Finished."},{"instruction":"Entra a Debian: proot-distro login debian","placeholder":"proot-distro login debian","pattern":"^proot-distro\\s+login\\s+debian\\s*$","hint":"Usa: proot-distro login debian","success":"Ahora estás dentro de un Debian completo. Aquí funcionan apt, /etc y todo lo demás. Con \"exit\" vuelves a Termux.","output":"root@localhost:~#"}]},"id":22,"order":22},{"type":"text","title":"Seguridad, límites y ética de tener una terminal potente","description":"Lo que conviene saber antes de instalar todo lo que aparece en un tutorial.","content":"\n<h2>Tu teléfono tiene tus cosas más personales</h2>\n<p>Ejecutar comandos en Termux es más seguro que dar permisos a una app desconocida… siempre que <strong>tú sepas qué estás ejecutando</strong>. Reglas simples:</p>\n<table>\n<tr><th>Regla</th><th>Por qué</th></tr>\n<tr><td>No pegues comandos que no entiendes</td><td>Un solo comando puede descargar y ejecutar un programa dañino (por ejemplo <code>curl ... | bash</code> de una fuente desconocida).</td></tr>\n<tr><td>Instala con <code>pkg</code> desde los repositorios oficiales</td><td>Los paquetes están revisados por la comunidad del proyecto.</td></tr>\n<tr><td>Concede permisos de Termux:API solo cuando los uses</td><td>Los scripts heredan esos permisos.</td></tr>\n<tr><td>No compartas tu llave privada SSH, tokens ni contraseñas</td><td>Son las llaves de tus cuentas.</td></tr>\n<tr><td>Mantén todo actualizado con <code>pkg upgrade</code></td><td>Corrige fallos de seguridad.</td></tr>\n</table>\n\n<h2>Herramientas de red y seguridad</h2>\n<p>Termux ofrece programas como <code>nmap</code> (mapeo de redes) o <code>hydra</code>. Aprender a usarlos es legítimo y útil para defender redes. Pero:</p>\n<div class=\"warn\">\n⚠️ Escanear o intentar acceder a redes, cuentas o dispositivos que <strong>no son tuyos</strong> y sin autorización expresa puede ser un delito en tu país (y viola los Términos de Uso de esta escuela). Practica solo en tu red, tus equipos, o laboratorios pensados para eso. Si quieres el camino correcto, sigue la <em>Academia de Ciberseguridad</em>.\n</div>\n\n<h2>Límites reales de Termux</h2>\n<ul>\n<li>No es una máquina virtual completa (aunque proot-distro se acerca).</li>\n<li>Apps gráficas de PC requieren configuración extra y son lentas.</li>\n<li>Los procesos en segundo plano dependen de las políticas de batería de Android.</li>\n<li>Sin root no puedes tocar cosas del sistema (y no lo necesitas para aprender).</li>\n</ul>\n\n<div class=\"tip\">\n💡 <strong>Respaldo:</strong> tus archivos de Termux viven en el almacenamiento interno de la app. Si desinstalas Termux, se borran. Copia lo importante a <code>~/storage</code> o súbelo a Git.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué es lo más seguro al encontrar un tutorial con un comando desconocido?","options":["Pegarlo de inmediato para ver qué pasa","Entender qué hace antes de ejecutarlo, y desconfiar de los que descargan y ejecutan scripts de fuentes desconocidas","Ejecutarlo como root","Compartirlo con amigos"],"correctIndex":1},"id":23,"order":23},{"type":"text","title":"Proyecto final y siguientes pasos","description":"Une todo: un mini panel de tu teléfono y una ruta para seguir en la Academia de Linux.","content":"\n<h2>Proyecto: tu \"panel de control\" en Termux</h2>\n<p>Con lo que aprendiste, este proyecto es totalmente alcanzable:</p>\n<ol>\n<li><strong>Crea un script</strong> <code>panel.sh</code> en tu HOME.</li>\n<li>Que muestre la <strong>fecha</strong> (<code>date</code>), el <strong>usuario</strong> (<code>whoami</code>) y el <strong>espacio libre</strong> (<code>df -h ~</code>).</li>\n<li>Que use <code>termux-battery-status</code> (con <code>jq</code>) para mostrar el <strong>porcentaje de batería</strong>.</li>\n<li>Que al final envíe una <strong>notificación</strong> con <code>termux-notification</code> que diga \"Panel listo\".</li>\n<li>Guárdalo en <code>~/.shortcuts</code> para lanzarlo con un widget.</li>\n<li>Súbelo a <strong>GitHub</strong> con Git: ya sabes hacerlo.</li>\n</ol>\n\n<div class=\"example\">\n<strong>Nivel extra:</strong> agrégale que, si la batería baja del 20%, use <code>termux-tts-speak</code> para avisarte en voz alta. Ese es tu primer \"servicio\" propio.\n</div>\n\n<h2>¿Qué sigue en la Academia de Linux?</h2>\n<table>\n<tr><th>Si quieres…</th><th>Sigue con…</th></tr>\n<tr><td>Dominar los comandos</td><td>Consola de Comandos: Primeros Pasos → Bash desde Cero</td></tr>\n<tr><td>Entender de dónde viene todo</td><td>Historia de Linux</td></tr>\n<tr><td>Practicar sin miedo</td><td>El Laboratorio de terminales de la academia</td></tr>\n<tr><td>Trabajar en equipo con código</td><td>Git y GitHub: de Cero a Experto</td></tr>\n<tr><td>Proteger sistemas</td><td>Academia de Ciberseguridad</td></tr>\n</table>\n\n<p>Tienes en el bolsillo una herramienta que profesionales de todo el mundo usan a diario. Ahora depende de ti seguir explorando.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué conviene guardar copias de tus proyectos en ~/storage o en Git?","options":["Porque Termux es de pago","Porque los archivos dentro de Termux se borran si desinstalas la app","Porque Android lo obliga","No es necesario"],"correctIndex":1},"id":24,"order":24}]',
  '{}'::jsonb
)
